/**
 * Optional practice written by Claude for ONE topic of the exam's verified syllabus. It appears only
 * when Claude is ready, sits beside the exam's own practice engine without touching it, and is
 * labelled for what it is: GovOS-authored, not an official previous-year question. The server has
 * already refused anything off-topic, malformed, or claiming an official origin. Nothing here is
 * scored or saved to the attempt history.
 */
const ClaudePracticePanel: React.FC<{ exam: Exam }> = ({ exam }) => {
  const topics = Array.from(new Set(exam.syllabus.map(t => (t.topicName || '').replace(/\s+/g, ' ').trim()).filter(Boolean)));
  const [ready, setReady] = useState<boolean>(false);
  const [topic, setTopic] = useState<string>(topics[0] || '');
  const [count, setCount] = useState<number>(3);
  const [difficulty, setDifficulty] = useState<'EASY' | 'MEDIUM' | 'HARD'>('MEDIUM');
  const [busy, setBusy] = useState<boolean>(false);
  const [error, setError] = useState<string>('');
  const [result, setResult] = useState<ClaudePracticeResult | null>(null);
  const [picked, setPicked] = useState<Record<number, number>>({});

  useEffect(() => {
    let live = true;
    claudeService.healthCached().then(h => { if (live) setReady(!!h?.ready); });
    return () => { live = false; };
  }, [exam.id]);

  if (!ready || topics.length === 0) return null;

  const write = async () => {
    if (busy || !topic) return;
    setBusy(true);
    setError('');
    setResult(null);
    setPicked({});
    const ticket = await claudeService.practice(exam.id, topic, count, difficulty);
    if (!ticket.ok) {
      setError(ticket.error);
      setBusy(false);
      return;
    }
    const done = await claudeService.waitForJob<ClaudePracticeResult>(ticket.data.jobId, { token: ticket.data.token, timeoutMs: 120_000 });
    if (!done.ok) {
      void claudeService.cancel(ticket.data.jobId, ticket.data.token);
      setError(done.error);
    } else if (done.data.status !== 'SUCCEEDED' || !done.data.result) {
      setError(done.data.errorMessage || 'No questions could be written.');
    } else {
      setResult(done.data.result);
    }
    setBusy(false);
  };

  return (
    <div className="glass-card" style={{ padding: '20px', marginTop: '20px', display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
        <h4 style={{ fontSize: '1.0rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>Practice written by Claude</h4>
        <span className="badge badge-pending" style={{ fontSize: '0.64rem' }}><Bot size={12} /> GOVOS-AUTHORED · NOT AN OFFICIAL PREVIOUS-YEAR QUESTION</span>
      </div>
      <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', lineHeight: 1.5 }}>
        Pick a topic from {exam.title}'s verified syllabus and Claude writes a few new questions on it. Each answer key is checked by a second, independent solve that is never shown the key, and a question where the two disagree is left out. They are practice, not past papers; they are not scored or saved to your history, and you should still check an answer against your study material.
      </div>
      <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap', alignItems: 'center' }}>
        <select value={topic} onChange={e => setTopic(e.target.value)} aria-label="Syllabus topic" style={{ minWidth: 0, maxWidth: '100%', flex: 1, padding: '9px 10px', borderRadius: 'var(--radius-md)', background: 'var(--bg-input)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', fontSize: '0.84rem' }}>
          {topics.map(t => <option key={t} value={t}>{t}</option>)}
        </select>
        <select value={count} onChange={e => setCount(Number(e.target.value))} aria-label="Number of questions" style={{ padding: '9px 10px', borderRadius: 'var(--radius-md)', background: 'var(--bg-input)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', fontSize: '0.84rem' }}>
          {[1, 2, 3, 4, 5].map(n => <option key={n} value={n}>{n} question{n > 1 ? 's' : ''}</option>)}
        </select>
        <select value={difficulty} onChange={e => setDifficulty(e.target.value as 'EASY' | 'MEDIUM' | 'HARD')} aria-label="Difficulty" style={{ padding: '9px 10px', borderRadius: 'var(--radius-md)', background: 'var(--bg-input)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', fontSize: '0.84rem' }}>
          <option value="EASY">Easy</option>
          <option value="MEDIUM">Medium</option>
          <option value="HARD">Hard</option>
        </select>
        <button className="btn btn-primary" onClick={write} disabled={busy} style={{ fontSize: '0.84rem', flexShrink: 0, display: 'inline-flex', alignItems: 'center', gap: '6px' }}>
          <RefreshCw size={14} className={busy ? 'animate-spin' : ''} /> {busy ? 'Writing…' : 'Write questions'}
        </button>
      </div>
      {error && (
        <div style={{ fontSize: '0.8rem', color: '#b71f1f' }}><AlertTriangle size={12} style={{ verticalAlign: '-2px' }} /> {error}</div>
      )}
      {result && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <div style={{ fontSize: '0.74rem', color: 'var(--text-muted)' }}>{result.label}{result.answerCheck === 'INDEPENDENT_SOLVE_AGREED' ? ' Every answer key was confirmed by an independent second solve.' : ''}</div>
          {result.questions.map((q, qi) => {
            const choice = picked[qi];
            return (
              <div key={qi} style={{ padding: '14px', borderRadius: 'var(--radius-md)', background: 'var(--surface-2)', border: '1px solid var(--border-color)' }}>
                <div style={{ fontSize: '0.92rem', fontWeight: 700, color: 'var(--text-primary)', marginBottom: '8px' }}>{qi + 1}. {q.stem}</div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                  {q.options.map((opt, oi) => {
                    const answered = choice !== undefined;
                    const right = oi === q.correct_index;
                    return (
                      <button
                        key={oi}
                        onClick={() => !answered && setPicked(prev => ({ ...prev, [qi]: oi }))}
                        style={{ textAlign: 'left', padding: '8px 12px', borderRadius: 'var(--radius-sm)', fontSize: '0.84rem', fontFamily: 'var(--font-sans)', cursor: answered ? 'default' : 'pointer', color: 'var(--text-primary)', background: answered && right ? 'var(--emerald-soft)' : answered && choice === oi ? 'var(--rose-soft)' : 'var(--surface-3)', border: `1px solid ${answered && right ? '#147a3a' : answered && choice === oi ? '#b71f1f' : 'var(--border-color)'}` }}
                      >
                        {String.fromCharCode(65 + oi)}. {opt}
                      </button>
                    );
                  })}
                </div>
                {choice !== undefined && (
                  <div style={{ marginTop: '8px', fontSize: '0.8rem', color: 'var(--text-secondary)', lineHeight: 1.5 }}>
                    <strong>{choice === q.correct_index ? 'Correct.' : `Not quite — the answer is ${String.fromCharCode(65 + q.correct_index)}.`}</strong> {q.explanation}
                  </div>
                )}
              </div>
            );
          })}
          {result.dropped.length > 0 && (
            <div style={{ fontSize: '0.72rem', color: 'var(--text-muted)' }}>{result.dropped.length} question{result.dropped.length > 1 ? 's' : ''} did not pass GovOS's checks (including the independent answer check) and {result.dropped.length > 1 ? 'were' : 'was'} left out.</div>
          )}
        </div>
      )}
    </div>
  );
};


// --------------------------------------------------------------------------
// Grounded answer engine for the GovOS assistant.
//
// Two kinds of question have to work: "where do I do X in this platform" (navigation)
// and "what does the notice say about X" (facts read out of SSC_CGL_EXAM, cited).
// Anything else falls back honestly: to Claude reading this exam's verified facts when it is
// available (checked on the server), and to the register's own reply when it is not.
// --------------------------------------------------------------------------

export interface AssistantAction {
  label: string;
  tab: GovOSTab;
  /** Exam Guide section 1-16, when the destination is inside the guide. */
  section?: number;
}

/**
 * What sort of claim an answer is — the safety rule in one field.
 * OFFICIAL: read from the verified register, cited. PLATFORM: how GovOS itself works.
 * GUIDANCE: derived advice, true of the register but not a quote from it.
 * CLARIFY: a question back. UNVERIFIED: not in the register; Claude is asked, when it is available.
 */
export type AssistantSourceKind = 'OFFICIAL' | 'PLATFORM' | 'GUIDANCE' | 'CLARIFY' | 'UNVERIFIED';

interface AssistantReply {
  /** Set when the thread has moved to another exam than the one open; the turn is stored under it. */
  switchedExamId?: string;
  text: string;
  verified: boolean;
  sourceKind?: AssistantSourceKind;
  /** True when the assistant could not place the question at all. */
  unresolved?: boolean;
  /** What this turn was about, recorded so the next message can inherit it. */
  subject?: string;
  /** The exact entry the answer is about, so the chat can link straight to it. */
  resourceLink?: { title: string; url: string; label: string };
  citation?: {
    documentTitle: string;
    pageNumber: number;
    clauseNumber: string;
    provenance: DataProvenance;
  };
  action?: AssistantAction;
}

/** Renders the assistant's plain text, turning **bold** markers into real bold runs. */
const renderAssistantText = (text: string): React.ReactNode[] =>
  text.split(/(\*\*[^*]+\*\*)/g).map((part, i) =>
    part.startsWith('**') && part.endsWith('**') && part.length > 4
      ? <strong key={i} style={{ color: '#4f46e5' }}>{part.slice(2, -2)}</strong>
      : <React.Fragment key={i}>{part}</React.Fragment>
  );

const has = (q: string, ...words: string[]) => words.some(w => q.includes(w));

/** Query flattened for matching: lowercase, punctuation and hyphens become spaces. */
const normaliseQuery = (s: string) => s.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

/** Whole-word match, tolerant of plurals and of stems written deliberately short ("eligib"). */
const matchesWord = (qWords: string[], word: string): boolean =>
  qWords.some(w =>
    w === word ||
    w === `${word}s` || w === `${word}es` ||
    (word.endsWith('s') && w === word.slice(0, -1)) ||
    (word.length >= 5 && w.startsWith(word))
  );

/**
 * How well one key describes the query.
 *
 * A multi-word key scores far above any single word, because it is a far more specific
 * statement of intent: "application practice" means the form simulator, while "practice"
 * alone means almost nothing. The words of a multi-word key need not be adjacent —
 * "application mock practice" still means the simulator — but adjacency scores higher.
 */
/** Like matchesWord, but forgiving a typo ("negetive"); used only when exact matching found nothing. */
const matchesWordLoose = (qWords: string[], word: string): boolean =>
  matchesWord(qWords, word) || qWords.some(w =>
    fuzzyWordEq(w, word) ||
    (w.endsWith('s') && fuzzyWordEq(w.slice(0, -1), word)) ||
    (w.endsWith('es') && fuzzyWordEq(w.slice(0, -2), word))
  );

const scoreKey = (qWords: string[], qNorm: string, key: string, loose: boolean = false): number => {
  const match = loose ? matchesWordLoose : matchesWord;
  const parts = normaliseQuery(key).split(' ').filter(Boolean);
  if (parts.length === 0) return 0;
  if (parts.length === 1) {
    return match(qWords, parts[0]) ? 1 + Math.min(parts[0].length, 12) * 0.12 : 0;
  }
  if (!parts.every(part => match(qWords, part))) return 0;
  return (qNorm.includes(parts.join(' ')) ? 6 : 4) + parts.length * 1.5;
};

/** Which words of the question a key accounts for (empty when the key does not match). */
const wordsCoveredByKey = (qWords: string[], key: string, loose: boolean): string[] => {
  const match = loose ? matchesWordLoose : matchesWord;
  const parts = normaliseQuery(key).split(' ').filter(Boolean);
  if (parts.length === 0 || !parts.every(part => match(qWords, part))) return [];
  return qWords.filter(w => parts.some(part => match([w], part)));
};

/**
 * Total score for an entry, counting each word of the question once. Without this, listing
 * both "channel" and "channels" as keys scored a single word twice and a weak, generic
 * match looked like a confident one.
 */
const scoreKeys = (query: string, keys: string[], loose: boolean = false): number => {
  const qNorm = normaliseQuery(query);
  const qWords = qNorm.split(' ').filter(Boolean);
  const scored = keys
    .map(key => ({ score: scoreKey(qWords, qNorm, key, loose), words: wordsCoveredByKey(qWords, key, loose) }))
    .filter(x => x.score > 0)
    .sort((a, b) => b.score - a.score);
  const credited = new Set<string>();
  let total = 0;
  scored.forEach(entry => {
    if (!entry.words.some(w => !credited.has(w))) return;   // adds nothing new
    total += entry.score;
    entry.words.forEach(w => credited.add(w));
  });
  return total;
};

/** Words that carry no intent; ignored when judging how much of a question was understood. */
const ASSISTANT_FILLER = new Set(['the', 'a', 'an', 'is', 'are', 'was', 'do', 'does', 'did', 'can', 'could', 'will', 'would', 'should',
  'i', 'me', 'my', 'we', 'you', 'your', 'it', 'its', 'this', 'that', 'these', 'those', 'to', 'for', 'of', 'in', 'on', 'at', 'from',
  'and', 'or', 'but', 'with', 'about', 'please', 'kindly', 'tell', 'give', 'show', 'want', 'need', 'get', 'know', 'there', 'here',
  'where', 'what', 'when', 'which', 'who', 'why', 'how', 'ssc', 'cgl', 'exam', 'govos', 'platform', 'app', 'sir', 'hai', 'hain', 'kya', 'kaise']);

/**
 * What a phrasing means, appended to the question before scoring. The candidate's words stay
 * (the reply still quotes them); the concept is added so the intent tables can see it.
 * Order matters only where two patterns could both fire; each appends, none replaces.
 */
const ASSISTANT_PARAPHRASES: { pattern: RegExp; means: string }[] = [
  { pattern: /\b(till|until|by) when\b|\bfill (in |up )?(the )?form\b|\bform (close|closes|closing|shut)|\bsubmit the form\b/, means: 'last date to apply' },
  { pattern: /\bwrong (tick|answer|option|mark|attempt)s?\b|\blose marks?\b|\bpenalt(y|ies)\b|\bdeduct|\bminus marks?\b|\bnegative\b/, means: 'negative marking' },
  { pattern: /\bhow much (do|does|will|would) (they|it|the job|the post|the government) pay\b|\bearn\b|\bstipend\b|\btake.?home\b|\bmonthly pay\b|\bpay of\b/, means: 'salary' },
  { pattern: /\b(running|walking|cycling|height|chest|fitness|endurance|physical|medical) (test|standard|standards|requirement|requirements|check)s?\b|\bphysically fit\b/, means: 'physical test' },
  { pattern: /\bhall (pass|ticket)\b|\be.?admit\b|\badmission certificate\b|\bcall letter\b/, means: 'admit card' },
  { pattern: /\bhow many (people|candidates|students|of us) (will|do|does|are) (they|it|get|they take|select)|\bhow many (will|do) they (take|select|recruit|pick)\b|\bseats\b|\bopenings\b|\bhow many (posts|services|jobs)\b/, means: 'vacancies' },
  { pattern: /\battempts?\b|\bhow many times can i (sit|appear|write|attempt|try)\b|\bchances\b/, means: 'attempts' },
  { pattern: /\b(final|fixed|confirmed) or tentative\b|\btentative\b|\bis (that|this|it) (final|fixed|confirmed)\b|\bcan (that|this|it) change\b/, means: 'tentative' },
  { pattern: /\bprelims?\b|\bpreliminary\b/, means: 'prelims' },
  { pattern: /\bmains?\b(?! (subject|topic))|\bmain exam\b/, means: 'mains' },
  { pattern: /\binterview\b|\bpersonality test\b/, means: 'interview' },
  { pattern: /\bcan i still (sit|apply|appear|write)\b|\bfinal year\b|\b(finishes|finishing|completes|completing) (next|this) year\b|\bawaiting (my )?result\b|\bresult (is )?awaited\b/, means: 'final year eligibility' },
  { pattern: /\bwhich (one|post|service) (should|do|would) i (choose|pick|prefer|go for)\b|\bwhich is better for me\b|\bwhat should i (choose|pick)\b/, means: 'which post should i choose' },
  { pattern: /\b(csat|paper 2|paper ii|gs paper 2)\b/, means: 'csat qualifying' },
  { pattern: /\bqualifying marks\b|\bminimum marks\b|\bpassing marks\b|\bsafe score\b/, means: 'cutoff' }
];

/** The question with what it means added, so a phrasing the tables never listed still lands. */
function expandParaphrases(q: string): string {
  const added: string[] = [];
  ASSISTANT_PARAPHRASES.forEach(({ pattern, means }) => {
    if (pattern.test(q) && !added.includes(means)) added.push(means);
  });
  return added.length > 0 ? `${q} ${added.join(' ')}` : q;
}

/**
 * The part of the question that asks. "my resources are limited, what is the fee" is a fee
 * question: the clause after the last question word is what has to be answered.
 */
function questionFocus(q: string): string | null {
  const parts = q.split(/\b(what|when|how much|how many|how|which|where|who|why|is there|are there|do i|can i|tell me|give me)\b/);
  if (parts.length < 3) return null;
  const focus = parts.slice(-2).join(' ').trim();
  return contentWordsOf(focus).length >= 1 && focus.length < q.length ? focus : null;
}

/** Ordinary English the typo corrector must leave alone; none of these is a typo of anything. */
const COMMON_WORDS = ['till', 'until', 'form', 'fill', 'pass', 'hall', 'thing', 'lose', 'wrong', 'tick', 'running', 'walking', 'test',
  'people', 'take', 'sit', 'still', 'next', 'year', 'finishes', 'finish', 'limited', 'about', 'exact', 'wall', 'says', 'june',
  'morning', 'every', 'forget', 'just', 'enough', 'choose', 'better', 'same', 'again', 'also', 'then', 'only', 'really', 'much',
  'many', 'more', 'less', 'first', 'last', 'before', 'after', 'again', 'once', 'twice', 'time', 'times', 'chance', 'chances',
  'money', 'earn', 'pays', 'paid', 'final', 'fixed', 'sure', 'true', 'real', 'actual', 'whole', 'entire', 'full', 'half',
  'these', 'those', 'them', 'they', 'their', 'have', 'has', 'been', 'being', 'were', 'will', 'shall', 'must', 'might', 'maybe',
  'yoga', 'video', 'saw', 'seen', 'read', 'heard', 'said', 'told', 'mean', 'means', 'meant', 'guess', 'think', 'thought',
  'good', 'best', 'well', 'fine', 'okay', 'right', 'left', 'high', 'low', 'long', 'short', 'late', 'early', 'soon', 'today',
  'tomorrow', 'week', 'month', 'months', 'days', 'date', 'dates', 'apply', 'applied', 'applying', 'appear', 'attempt', 'tier',
  'prelims', 'mains', 'main', 'interview', 'stage', 'stages', 'paper', 'papers', 'marks', 'mark', 'score', 'scores', 'post',
  'posts', 'service', 'services', 'job', 'jobs', 'exam', 'exams', 'into', 'onto', 'over', 'under', 'through', 'without', 'within'];

/** Every word the assistant can match, used to correct typos before matching. Built once. */
let assistantVocabulary: Set<string> | null = null;
const assistantVocab = (): Set<string> => {
  if (assistantVocabulary) return assistantVocabulary;
  const vocab = new Set<string>();
  const add = (phrase: string) => normaliseQuery(phrase).split(' ').forEach(w => { if (w.length >= 4) vocab.add(w); });
  PLATFORM_MAP.forEach(entry => entry.keys.forEach(add));
  FACT_INTENTS.forEach(entry => entry.keys.forEach(add));
  // Whole words candidates type, including expansions of the stems used as keys.
  ['where', 'what', 'when', 'which', 'how', 'why', 'who', 'this', 'that', 'platform', 'section', 'page', 'find', 'open', 'show',
    'tell', 'give', 'need', 'want', 'there', 'here', 'eligible', 'eligibility', 'qualification', 'qualify',
    'syllabus', 'admit', 'card', 'download', 'vacancy', 'vacancies', 'salary', 'notification', 'notice', 'application',
    'registration', 'corrigendum', 'cutoff', 'result', 'answer', 'paper', 'papers', 'practice', 'typing', 'documents',
    'certificate', 'category', 'relaxation', 'marking', 'negative', 'pattern', 'question', 'questions', 'resources',
    'calendar', 'timeline', 'roadmap', 'bookmark', 'simulator'].forEach(w => vocab.add(w));
  ALL_EXAMS.forEach(ex => (ex.resources || []).forEach(r => { add(r.title); add(r.subject); }));
  COMMON_WORDS.forEach(w => vocab.add(w));
  ASSISTANT_PARAPHRASES.forEach(pp => add(pp.means));
  assistantVocabulary = vocab;
  return vocab;
};

/**
 * Fix obvious typos before any matching happens — otherwise "whree is thr typing test tool"
 * never even registers as a "where" question. Only words of four letters or more are
 * touched, and only when they are within a typo's distance of a word the assistant knows.
 */
function correctAssistantQuery(query: string): { text: string; corrections: { typed: string; readAs: string }[] } {
  const vocab = assistantVocab();
  const corrections: { typed: string; readAs: string }[] = [];
  const words = normaliseQuery(query).split(' ').filter(Boolean).map(word => {
    if (word.length < 4 || vocab.has(word)) return word;
    if (word.endsWith('s') && vocab.has(word.slice(0, -1))) return word;
    let best = '';
    vocab.forEach(candidate => {
      // a typo rarely changes the first letter, and requiring it stops wild corrections
      if (candidate[0] !== word[0]) return;
      const near = fuzzyWordEq(word, candidate) ||
        (word.length === 4 && candidate.length <= 5 && editDistanceShort(word, candidate) <= 1);
      if (!near) return;
      if (!best || Math.abs(candidate.length - word.length) < Math.abs(best.length - word.length)) best = candidate;
    });
    if (best) {
      corrections.push({ typed: word, readAs: best });
      return best;
    }
    return word;
  });
  return { text: words.join(' '), corrections };
}

/** Distance for short words, transpositions counted as one edit ("crad" → "card"). */
function editDistanceShort(a: string, b: string): number {
  const d: number[][] = Array.from({ length: a.length + 1 }, (_, i) => Array.from({ length: b.length + 1 }, (_, j) => (i === 0 ? j : j === 0 ? i : 0)));
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost);
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
    }
  }
  return d[a.length][b.length];
}

/** What the button should say for a given kind of entry. */
const resourceActionLabel = (r: ResourceItem): string => {
  switch (r.resourceFormat) {
    case 'DIRECT_PDF': return 'Open the PDF';
    case 'ONLINE_TOOL': return 'Launch the tool';
    case 'YOUTUBE_COURSE': return 'Watch the video';
    case 'YOUTUBE_CHANNEL': return 'Open the channel';
    default: return 'Open the official page';
  }
};

/** A direct link to one entry, for an answer that is about that entry. */
const linkFor = (r: ResourceItem) => ({ title: r.title, url: r.url, label: resourceActionLabel(r) });

/** Words that point back at the conversation instead of naming anything. */
const DEICTIC_WORDS = /\b(it|its|this|that|these|those|them|they|there|same|again|instead|one|ones)\b/;

/**
 * Expand a follow-up with the subject the conversation already settled on, so "when is it?"
 * and "what about this post?" carry their meaning. Returns null when there is nothing to
 * inherit — an invented subject would be worse than a clarifying question.
 */
export function resolveWithHistory(message: string, history: ConversationTurn[]): { text: string; inherited: string } | null {
  const lastSubject = [...history].reverse().find(t => t.role === 'assistant' && t.subject)?.subject;
  const lastUserWords = [...history].reverse()
    .filter(t => t.role === 'user')
    .map(t => contentWordsOf(t.text))
    .find(words => words.length > 0);
  const inherited = lastSubject || (lastUserWords ? lastUserWords.join(' ') : '');
  if (!inherited) return null;
  // Append what the tables match, show the candidate the label they read.
  const reenter = SUBJECT_TO_CANONICAL[inherited] || inherited;
  return { text: `${message} ${reenter}`.trim(), inherited };
}

// ---- what a resource is for ------------------------------------------------------------
// A PDF is not study material because it is a PDF, and a YouTube link is not a lesson because it
// is on YouTube. The role is what the content is *for*, and only learning material belongs in the
// Resource Library. This mirrors tools/exam_builder/resource_roles.py `classify_resource_item`;
// both are held to tools/exam_builder/resource_role_cases.json (the Python suite and
// `npm run check:frontend`), so the two cannot drift apart.
const RESOURCE_ROLES: ResourceRole[] = [
  'EXAM_PAGE', 'NOTIFICATION', 'CORRIGENDUM', 'SYLLABUS', 'EXAM_PATTERN', 'QUESTION_PAPER', 'ANSWER_KEY',
  'ADMIT_CARD', 'RESULT', 'APPLICATION_PORTAL', 'CUTOFF', 'CALENDAR', 'OTR_PORTAL', 'OFFICIAL_PORTAL',
  'APPLICATION_GUIDE', 'EXAM_GUIDE', 'EXAM_DAY_INSTRUCTIONS', 'STUDY_MATERIAL', 'LECTURE_VIDEO', 'PRACTICE_TOOL',
  'DISCOVERY_SIGNAL', 'UNKNOWN'
];
const LEARNING_ROLES: ResourceRole[] = ['STUDY_MATERIAL', 'LECTURE_VIDEO', 'PRACTICE_TOOL'];
const OFFICIAL_RESOURCE_SUBJECTS = ['official gazette', 'official portal', 'official notices', 'previous year papers'];
const STUDY_REFERENCE = /constitution|india\s+code|\bcentral\s+acts?\b|statutes?|bare\s+acts?|textbooks?|ncert/i;
const ITEM_ROLE_RULES: Array<[ResourceRole, RegExp]> = [
  ['ANSWER_KEY', /answer\s*keys?|response\s+sheets?/i],
  ['QUESTION_PAPER', /question\s+papers?|previous\s+year|\bpyqs?\b|question\s+booklet|official\s+question\s+paper/i],
  ['CUTOFF', /cut[\s-]*off|qualifying\s+marks/i],
  ['CALENDAR', /\bcalendar\b|exam(ination)?\s+schedule|time\s*table/i],
  ['RESULT', /\bresults?\b|merit\s+list|selection\s+list|qualified\s+candidates/i],
  ['ADMIT_CARD', /admit\s*card|hall\s*ticket|call\s*letter/i],
  ['CORRIGENDUM', /corrigend|addend|re-?open|amendment|extension\s+of/i],
  ['SYLLABUS', /syllabus|scheme\s+(of|and)\s+exam/i],
  ['OTR_PORTAL', /one[\s-]*time[\s-]*registration|\botr\b/i],
  ['APPLICATION_PORTAL', /application\s+portal|apply\s+(online|here)|online\s+application|\bapplication\b.*\bportal/i],
  ['NOTIFICATION', /notification|notice|advertisement|press\s+note|recruitment/i]
];
const APPLICATION_PORTAL_WORDS = /application\s+portal|apply\s+(online|here)|online\s+application/i;
const ARCHIVE_WORDS = /gazette|\barchive\b/i;
const PORTAL_WORDS = /\bportal\b|official\s+(web)?site/i;

/** A video's role from its title: a walkthrough of applying, news (a lead), or a lesson. */
const videoRoleOf = (words: string): ResourceRole => {
  if (/how\s+to\s+(apply|fill|register)|application\s+form|registration\s+process|\botr\b|one[\s-]*time[\s-]*registration|fill(ing)?\s+(the\s+)?(online\s+)?form|apply\s+online|step[\s-]+by[\s-]+step/i.test(words)) return 'APPLICATION_GUIDE';
  if (/\b(released?|out\s+now|is\s+out|declared|breaking|update|announced|notification\s+out|news)\b/i.test(words)) return 'DISCOVERY_SIGNAL';
  // An explanation of the exam, a lesson, or a title that says nothing: each is learning.
  return 'LECTURE_VIDEO';
};

export const resourceRoleOf = (r: Pick<ResourceItem, 'title' | 'type' | 'resourceFormat' | 'subject' | 'officialTag'> & { role?: string }): ResourceRole => {
  if (r.role && (RESOURCE_ROLES as string[]).includes(r.role)) return r.role as ResourceRole;
  const subject = String(r.subject || '').trim().toLowerCase();
  const words = `${r.title || ''} ${r.officialTag || ''}`;
  if (r.type === 'THIRD_PARTY' || r.resourceFormat === 'EXTERNAL_PAGE') {
    // A third-party page is filed by what it carries; it is never official whatever it carries.
    const hit = ITEM_ROLE_RULES.find(([, re]) => re.test(words));
    if (hit) return hit[0];
    return subject === 'previous year papers' ? 'QUESTION_PAPER' : 'STUDY_MATERIAL';
  }
  if (r.type === 'VIDEO_LECTURE' || r.resourceFormat === 'YOUTUBE_COURSE' || r.resourceFormat === 'YOUTUBE_CHANNEL') return videoRoleOf(words);
  if (r.type === 'ONLINE_TOOL' || r.resourceFormat === 'ONLINE_TOOL') return 'PRACTICE_TOOL';
  if (subject === 'previous year papers') return ITEM_ROLE_RULES[0][1].test(words) ? 'ANSWER_KEY' : 'QUESTION_PAPER';
  if (OFFICIAL_RESOURCE_SUBJECTS.includes(subject)) {
    if (STUDY_REFERENCE.test(words)) return 'STUDY_MATERIAL';
    // A portal that takes applications names that first, even when it also serves admit cards.
    if (APPLICATION_PORTAL_WORDS.test(words)) return 'APPLICATION_PORTAL';
    // A card naming three or more kinds of document is a general portal, not one of them.
    const named = new Set(ITEM_ROLE_RULES.filter(([, re]) => re.test(words)).map(([role]) => role));
    if (named.size >= 3 || (PORTAL_WORDS.test(words) && [...named].every(role => role === 'NOTIFICATION'))) return 'OFFICIAL_PORTAL';
    // A gazette or an archive holds every body's notifications, not this exam's.
    if (ARCHIVE_WORDS.test(words) && !named.has('QUESTION_PAPER') && !named.has('ANSWER_KEY')) return 'OFFICIAL_PORTAL';
    const hit = ITEM_ROLE_RULES.find(([, re]) => re.test(words));
    return hit ? hit[0] : 'OFFICIAL_PORTAL';
  }
  // A learning subject. Still, an official document filed under one by mistake is not study material.
  const official = ITEM_ROLE_RULES.slice(0, 2).find(([, re]) => re.test(words));
  return official ? official[0] : 'STUDY_MATERIAL';
};

export const isLearningResource = (r: ResourceItem): boolean => LEARNING_ROLES.includes(resourceRoleOf(r));

/** The section of an exam's page an entry is shown in. Only learning material is in the Resource Library. */
export type ResourcePlacement = 'RESOURCES' | 'PRACTICE' | 'APPLICATION' | 'OFFICIAL_LINKS' | 'CORRIGENDA' | 'ADMIT_CARD'
  | 'RESULTS' | 'SYLLABUS' | 'CUTOFFS' | 'EXAM_DAY' | 'DATES' | 'PATTERN' | 'OVERVIEW' | 'NONE';
export type ResourceSection = Exclude<ResourcePlacement, 'NONE'>;

/** The one placement model: role -> section. Mirrors tools/exam_builder/resource_roles.py SECTION_FOR_ROLE;
 *  both are held to resource_role_cases.json ("sectionForRole"). null: never shown as a resource -- a lead
 *  (news) is a reason to look, not information. */
export const RESOURCE_SECTION: Record<ResourceRole, ResourceSection | null> = {
  NOTIFICATION: 'OFFICIAL_LINKS', EXAM_PAGE: 'OFFICIAL_LINKS', OFFICIAL_PORTAL: 'OFFICIAL_LINKS',
  CORRIGENDUM: 'CORRIGENDA', SYLLABUS: 'SYLLABUS', EXAM_PATTERN: 'PATTERN', QUESTION_PAPER: 'PRACTICE',
  ANSWER_KEY: 'PRACTICE', ADMIT_CARD: 'ADMIT_CARD', RESULT: 'RESULTS', CUTOFF: 'CUTOFFS', CALENDAR: 'DATES',
  APPLICATION_PORTAL: 'APPLICATION', OTR_PORTAL: 'APPLICATION', APPLICATION_GUIDE: 'APPLICATION',
  EXAM_GUIDE: 'OVERVIEW', EXAM_DAY_INSTRUCTIONS: 'EXAM_DAY', STUDY_MATERIAL: 'RESOURCES', LECTURE_VIDEO: 'RESOURCES',
  PRACTICE_TOOL: 'RESOURCES', DISCOVERY_SIGNAL: null, UNKNOWN: null
};

/** Each section as the exam page names it, with its stable section number (the deep-link id). */
export const SECTION_OF_PLACEMENT: Record<ResourceSection, { num: number; label: string }> = {
  OVERVIEW: { num: 1, label: 'Overview' }, DATES: { num: 2, label: 'Dates & Timeline' },
  APPLICATION: { num: 4, label: 'Application & Documents' }, PATTERN: { num: 5, label: 'Exam Pattern' },
  SYLLABUS: { num: 6, label: 'Syllabus' }, RESOURCES: { num: 8, label: 'Resources' },
  PRACTICE: { num: 9, label: 'Practice & PYQs' }, CUTOFFS: { num: 10, label: 'Cutoff History' },
  OFFICIAL_LINKS: { num: 12, label: 'Official Portals & Links' }, CORRIGENDA: { num: 13, label: 'Corrigenda Log' },
  ADMIT_CARD: { num: 14, label: 'Admit Card' }, EXAM_DAY: { num: 15, label: 'Exam Day' },
  RESULTS: { num: 16, label: 'Results & Next Steps' }
};

export const resourcePlacementOf = (r: ResourceItem): ResourcePlacement => RESOURCE_SECTION[resourceRoleOf(r)] || 'NONE';

/** Plain words for a role, for a card's kicker. */
const RESOURCE_ROLE_LABEL: Record<ResourceRole, string> = {
  EXAM_PAGE: 'Exam page', NOTIFICATION: 'Notification', CORRIGENDUM: 'Corrigendum / revision', SYLLABUS: 'Syllabus',
  EXAM_PATTERN: 'Exam pattern', QUESTION_PAPER: 'Question papers', ANSWER_KEY: 'Answer keys', ADMIT_CARD: 'Admit card',
  RESULT: 'Results', APPLICATION_PORTAL: 'Application portal', CUTOFF: 'Cut-offs', CALENDAR: 'Exam calendar',
  OTR_PORTAL: 'One-time registration', OFFICIAL_PORTAL: 'Official portal', APPLICATION_GUIDE: 'How to apply',
  EXAM_GUIDE: 'About the exam', EXAM_DAY_INSTRUCTIONS: 'Exam-day instructions', STUDY_MATERIAL: 'Study material',
  LECTURE_VIDEO: 'Lessons', PRACTICE_TOOL: 'Practice tool', DISCOVERY_SIGNAL: 'Lead', UNKNOWN: 'Link'
};

/**
 * Counts in answer text come from the register, not from whatever was true when the
 * sentence was written: {posts}, {resources}, {syllabus}, {exam}. {resources} counts only what the
 * Resource Library lists -- learning material.
 */
const fillCounts = (text: string, exam: Exam): string => text
  .replace(/\{posts\}/g, String(exam.posts.length))
  .replace(/\{resources\}/g, String((exam.resources || []).filter(isLearningResource).length))
  .replace(/\{syllabus\}/g, String(exam.syllabus.length))
  .replace(/\{exam\}/g, exam.title);

/** A short phrase naming what each intent is about, recorded on the turn for follow-ups. */
const FACT_SUBJECTS: Record<string, string> = {
  targetPost: 'your target post',
  nextStep: 'what to do next',
  studyPlan: 'what to study',
  age: 'the age limits',
  eligibility: 'eligibility',
  dates: 'the important dates',
  pattern: 'the exam pattern',
  vacancy: 'the vacancies',
  pay: 'the pay by post',
  syllabus: 'the syllabus',
  fee: 'the application fee',
  resources: 'the resources',
  admitCard: 'the admit card',
  cutoff: 'the cutoffs',
  apply: 'the application process',
  practice: 'practice and mock tests',
  attempts: 'the number of attempts',
  physical: 'the physical standards',
  tentative: 'whether the dates are final'
};

/**
 * The phrase that re-enters each intent when a follow-up inherits it. A subject label like
 * "the pay by post" is for the candidate to read; "salary" is what the tables match.
 */
const FACT_CANONICAL: Record<string, string> = {
  targetPost: 'my target post', nextStep: 'what should i do next', studyPlan: 'what should i study', age: 'age limit',
  eligibility: 'eligibility', dates: 'exam date', pattern: 'exam pattern', vacancy: 'vacancies', pay: 'salary',
  syllabus: 'syllabus', fee: 'fee', resources: 'resources', admitCard: 'admit card', cutoff: 'cutoff', apply: 'apply',
  practice: 'practice', attempts: 'attempts', physical: 'physical test', tentative: 'tentative'
};
const SUBJECT_TO_CANONICAL: Record<string, string> = Object.fromEntries(
  Object.entries(FACT_SUBJECTS).map(([id, label]) => [label, FACT_CANONICAL[id] || label])
);

/** Content words of a question: what the assistant has to account for before answering. */
const contentWordsOf = (q: string): string[] =>
  normaliseQuery(q).split(' ').filter(w => w.length > 2 && !ASSISTANT_FILLER.has(w) && !/^\d+$/.test(w));

/**
 * True when a message names nothing of its own — "when is it?", "what about that?" — and so
 * has to borrow its subject from the conversation. A message that does name something
 * ("am I eligible?") must NOT borrow, or it would answer the previous question again.
 */
const needsInheritedSubject = (q: string): boolean =>
  contentWordsOf(q).filter(w => !DEICTIC_WORDS.test(w)).length === 0;

/**
 * The candidate named a specific thing that lives in the library ("typing test tool",
 * "constitution pdf"). Answering with the item beats answering with the section.
 */
export function namedResourceAnswer(q: string, minScore: number = 6, exam: Exam = SSC_CGL_EXAM): { reply: AssistantReply; score: number } | null {
  // Only this exam's library. A candidate inside UPSC must not be handed an SSC document.
  const library = exam.resources || [];
  // Scoring weights a term by how few entries carry it, which says nothing in a library of
  // one or two: every word is then "rare" and the single entry answers everything. Claiming
  // the candidate named a specific document needs a library big enough for the match to
  // mean something; below that, a section answer is the honest one.
  if (library.length < 5) return null;
  const { results } = rankResourcesForQuery(q, library, 3);
  if (results.length === 0 || results[0].score < minScore) return null;
  const top = results[0].resource;
  // Route to where the entry is actually shown: only learning material is in Resources. A lead is not
  // offered at all, and nothing is said about a card that a section does not hold.
  const placement = resourcePlacementOf(top);
  if (placement === 'NONE') return null;
  const where = SECTION_OF_PLACEMENT[placement];
  const others = results.slice(1, 3).filter(x => resourcePlacementOf(x.resource) === placement).map(x => x.resource.title);
  const inLibrary = placement === 'RESOURCES';
  const reply: AssistantReply = {
    verified: true,
    sourceKind: top.provenance?.verificationLevel === 'OFFICIALLY_VERIFIED' ? 'OFFICIAL' : 'GUIDANCE',
    subject: top.subject,
    resourceLink: linkFor(top),
    text: inLibrary
      ? `**${top.title}** — ${top.author}.${top.recommendedFor ? `\n\nBest for: ${top.recommendedFor}` : ''}${others.length > 0 ? `\n\nAlso in the library: ${others.join('; ')}.` : ''}\n\nThe link below opens it on the publisher's own site; the card in Resources shows when it was last checked.`
      : `**${top.title}** — ${top.author}.\n\nI found it under **${where.label}**.${others.length > 0 ? ` Also there: ${others.join('; ')}.` : ''}\n\nThe link below opens it on the publisher's own site.`,
    action: { label: `Open ${where.label}`, tab: 'EXAM_DETAIL', section: where.num }
  };
  return { reply, score: results[0].score };
}

/** The best-scoring entry of a keyed table — never merely the first one that matches. */
function bestMatch<T extends { keys: string[] }>(query: string, table: T[], loose: boolean = false): { entry: T; score: number } | null {
  let bestEntry: T | null = null;
  let bestScore = 0;
  for (const entry of table) {
    const score = scoreKeys(query, entry.keys, loose);
    if (score > bestScore) {
      bestEntry = entry;
      bestScore = score;
    }
  }
  return bestEntry ? { entry: bestEntry, score: bestScore } : null;
}

/**
 * Factual intents, scored the same way, so where a branch sits in this file no longer
 * decides which question it answers.
 */
const FACT_INTENTS: { id: string; keys: string[] }[] = [
  { id: 'targetPost', keys: ['this post', 'that post', 'my post', 'my target post', 'the post i selected', 'my selected post', 'about this post', 'which post should i choose', 'which one should i choose', 'which is better for me'] },
  { id: 'nextStep', keys: ['what should i do next', 'what next', 'next step', 'what now', 'where do i start', 'how do i start', 'where should i begin', 'what to do now', 'guide me'] },
  { id: 'studyPlan', keys: ['what should i study', 'what to study first', 'where should i start studying', 'how should i study', 'study first', 'what should i prepare'] },
  { id: 'age', keys: ['age limit', 'maximum age', 'minimum age', 'age relaxation', 'how old', 'upper age', 'age criteria', 'crucial date', 'age as on', 'too old', 'age bar'] },
  { id: 'eligibility', keys: ['eligib', 'qualification', 'graduate', 'graduation', 'degree', 'b tech', 'btech', 'can i apply', 'final year eligibility', 'can i still'] },
  { id: 'dates', keys: ['last date', 'deadline', 'closing date', 'application date', 'when can i apply', 'apply by', 'important date', 'exam date', 'when is the exam', 'notification date', 'tier 1 exam', 'tier 2 exam', 'when is tier', 'exam schedule', 'exam month', 'which month', 'last date to apply', 'when is prelims', 'prelims date', 'when is mains', 'mains date', 'when is the interview', 'interview date', 'when is'] },
  { id: 'pattern', keys: ['negative marking', 'marking scheme', 'exam pattern', 'pattern', 'how many questions', 'how many marks', 'duration', 'tier 1', 'tier 2', 'paper pattern', 'dest', 'data entry speed test', 'qualifying', 'csat qualifying', 'wrong answer', 'penalty'] },
  { id: 'vacancy', keys: ['vacancy', 'vacancies', 'how many post', 'number of post', 'seats', 'how many services', 'which services', 'services can i get', 'posts can i get', 'openings'] },
  { id: 'pay', keys: ['salary', 'pay level', 'pay scale', 'in hand', 'grade pay', 'how much do they pay', 'earn', 'stipend', 'take home', 'pay of'] },
  { id: 'syllabus', keys: ['syllabus', 'what to study', 'topics'] },
  { id: 'fee', keys: ['fee', 'payment', 'how much to pay', 'application fee', 'fees'] },
  { id: 'resources', keys: ['resource', 'material', 'book', 'pdf', 'video', 'ncert', 'free course', 'youtube', 'channel', 'coaching', 'teacher'] },
  { id: 'admitCard', keys: ['admit card', 'hall ticket', 'hall pass', 'e admit card', 'admission certificate', 'call letter'] },
  { id: 'cutoff', keys: ['cutoff', 'cut off', 'marks needed', 'safe score', 'qualifying marks', 'minimum marks', 'csat cutoff'] },
  { id: 'attempts', keys: ['attempts', 'number of attempts', 'how many attempts', 'how many times can i', 'chances'] },
  { id: 'physical', keys: ['physical test', 'physical standard', 'physical standards', 'running test', 'walking test', 'fitness test', 'height', 'chest', 'medical standard'] },
  { id: 'tentative', keys: ['tentative', 'is that final', 'is it final', 'final or tentative', 'confirmed', 'fixed date', 'can it change'] },
  { id: 'apply', keys: ['apply', 'application', 'otr', 'registration', 'photo', 'signature'] },
  { id: 'practice', keys: ['practice', 'mock', 'test', 'pyq', 'previous year'] }
];
const asksLocation = (q: string) => /\b(where|which (tab|section|page|part)|how do i|how can i|how should i|how to|what should i|navigate|find|locate|go to|open|show me|take me|check .* (in|on) (this|the) (platform|app|site|website)|in this platform)\b/.test(q);

/**
 * Whether an official document is on record as printing this post's classification.
 *
 * Absence is not a claim that the classification is wrong — the document is silent, not
 * opposed. It means GovOS has no published source for it, so it is shown as the record's
 * reading rather than as the authority's own word.
 */
const classificationIsConfirmed = (post: { id: string }): boolean =>
  Object.prototype.hasOwnProperty.call(CLASSIFICATION_CONFIRMED, post.id);

/**
 * What to print on a stage's badge.
 *
 * `tier` holds the frontend's own vocabulary (TIER_1), which no authority uses and no
 * candidate of an exam with phases or a single paper would recognise. Where the stage's own
 * name carries a label the authority printed, that is shown instead.
 */
const stageBadge = (stage: { tier: string; stageName: string; stageNumber: number }): string => {
  const printed = /\b(?:tier|phase|stage|paper|session|round)[\s\-\u2013]*(?:[IVXL]{1,4}|\d{1,2}|[A-H])\b/i.exec(stage.stageName || '');
  if (printed) return printed[0].toUpperCase();
  // TIER_1 is this codebase's vocabulary, not an authority's, and an exam whose stages are
  // phases, screenings or a single paper should not be told it has tiers. Where the
  // record's label is that vocabulary, the stage's own position is shown instead, which is
  // true of every exam; a label that means something on its own ("INTERVIEW") is kept.
  const value = (stage.tier || '').replace(/_/g, ' ').trim();
  if (/^TIER\s*\d+$/i.test(value)) return `STAGE ${stage.stageNumber}`;
  return value;
};

/** Non-superseded date of a given type for the exam in hand, if the register has one. */
const dateOfType = (type: string, exam: Exam = SSC_CGL_EXAM) =>
  exam.dates.find(d => d.type === type && d.status !== 'SUPERSEDED') ||
  exam.dates.find(d => d.type === type);

/** A cut-off's figure: the Tier-1 column where the source labels it so, else its own value. */
const cutoffFigure = (c: CutoffEntry) => (c.tier1Cutoff ?? c.value ?? 'not stated');

const citeFrom = (provenance: DataProvenance | undefined, fallbackTitle: string) => (provenance ? {
  documentTitle: provenance.documentTitle || fallbackTitle,
  pageNumber: provenance.pageNumber || 1,
  clauseNumber: provenance.clauseNumber || 'See source document',
  provenance
} : undefined);

