// ==========================================================================
// ResourceLibrary.tsx — organised, searchable study-resource library (Section 08)
// ==========================================================================

type ResourceTypeGroup = 'ALL' | 'OFFICIAL' | 'BOOKS' | 'VIDEO' | 'TOOLS' | 'THIRD_PARTY';

const RESOURCE_TYPE_GROUPS: { key: ResourceTypeGroup; label: string; types: ResourceItem['type'][] }[] = [
  { key: 'OFFICIAL', label: 'Official Documents & Portals', types: ['OFFICIAL_PDF', 'OFFICIAL_PORTAL'] },
  { key: 'BOOKS', label: 'Books & Handbooks', types: ['RECOMMENDED_BOOK', 'SIMPLIFIED_GUIDE'] },
  { key: 'VIDEO', label: 'Video Courses', types: ['VIDEO_LECTURE'] },
  { key: 'TOOLS', label: 'Practice Tools', types: ['ONLINE_TOOL'] },
  { key: 'THIRD_PARTY', label: 'Third-party (not official)', types: ['THIRD_PARTY'] }
];

// Display order for subject groups: primary sources first, then foundations, then subjects.
const RESOURCE_SUBJECT_ORDER: ResourceItem['subject'][] = [
  'Official Gazette',
  'Foundation Textbooks & Open Courses',
  'General Awareness & Static GK',
  'Current Affairs & Governance',
  'Banking & Financial Awareness',
  'Quantitative Aptitude',
  'Reasoning',
  'English Comprehension',
  'Computer & Typing'
];

const resourceTypeLabel = (type: ResourceItem['type']): string => {
  switch (type) {
    case 'OFFICIAL_PDF': return 'Official Document';
    case 'OFFICIAL_PORTAL': return 'Official Portal';
    case 'VIDEO_LECTURE': return 'Video Course';
    case 'RECOMMENDED_BOOK': return 'Recommended Book';
    case 'SIMPLIFIED_GUIDE': return 'Handbook';
    case 'ONLINE_TOOL': return 'Practice Tool';
    case 'THIRD_PARTY': return 'Third-party link';
    default: return 'Resource';
  }
};

const resourceTypeColor = (type: ResourceItem['type']): string => {
  switch (type) {
    case 'OFFICIAL_PDF':
    case 'OFFICIAL_PORTAL': return '#137638';
    case 'VIDEO_LECTURE': return '#b71f1f';
    case 'ONLINE_TOOL':
    case 'THIRD_PARTY': return '#af5109';
    default: return '#4f46e5';
  }
};

const ResourceTypeIcon: React.FC<{ type: ResourceItem['type']; size?: number }> = ({ type, size = 14 }) => {
  const color = resourceTypeColor(type);
  switch (type) {
    case 'OFFICIAL_PORTAL':
    case 'THIRD_PARTY': return <Globe size={size} color={color} />;
    case 'VIDEO_LECTURE': return <PlayCircle size={size} color={color} />;
    case 'ONLINE_TOOL': return <Zap size={size} color={color} />;
    case 'RECOMMENDED_BOOK':
    case 'SIMPLIFIED_GUIDE': return <BookOpen size={size} color={color} />;
    default: return <FileText size={size} color={color} />;
  }
};

const formatVerifiedDate = (iso: string): string => {
  const d = new Date(iso + 'T00:00:00');
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
};

const isExternalUrl = (value?: string): value is string => !!value && /^https?:\/\//i.test(value);

interface ResourceLibraryProps {
  /** False when the library is its own top-level tab rather than guide section 08. */
  showSectionNumber?: boolean;
  exam: Exam;
  onOpenResource: (resource: ResourceItem) => void;
  onOpenProvenanceModal: (provenance: DataProvenance) => void;
}

/** YouTube channel id from a /channel/UC… URL, or null. */
const channelIdOf = (url: string): string | null => {
  const m = url.match(/\/channel\/(UC[\w-]+)/);
  return m ? m[1] : null;
};

const formatFetched = (iso: string | null | undefined): string =>
  iso ? new Date(iso).toLocaleString('en-IN', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) : 'not yet';

/** A verifier-added entry rendered through the same card as the static library. */
const additionToResource = (a: ResourceAddition): ResourceItem => {
  const date = a.addedAt.slice(0, 10);
  // The server decides the kind from the URL's host. Anything it did not call official is never shown as official.
  const kind = a.sourceKind || 'THIRD_PARTY';
  const common = {
    id: a.id,
    title: a.title,
    subject: a.subject as ResourceItem['subject'],
    author: a.author,
    resourceFormat: a.resourceFormat,
    url: a.url,
    description: a.description
  };
  if (kind === 'OFFICIAL') {
    return {
      ...common,
      type: a.resourceFormat === 'DIRECT_PDF'
        ? 'OFFICIAL_PDF'
        : a.resourceFormat === 'YOUTUBE_COURSE' || a.resourceFormat === 'YOUTUBE_CHANNEL'
          ? 'VIDEO_LECTURE'
          : 'OFFICIAL_PORTAL',
      recommendedFor: 'Added after a live official-domain search and a verifier\'s review. Open it to confirm it fits what you need.',
      officialTag: `ADDED ${date} · VERIFIER-APPROVED FROM LIVE SOURCE RESEARCH`,
      provenance: {
        id: `prov-${a.id}`,
        documentTitle: a.title,
        officialUrl: a.url,
        publishedDate: date,
        verifiedDate: date,
        verifiedBy: 'GovOS verifier — promoted in the Trust Panel after a live official-domain search',
        taxonomyType: 'FACT',
        verificationLevel: 'OFFICIALLY_VERIFIED',
        excerptText: `Added to the library at runtime from Live Source Research${a.findingId ? ` finding #${a.findingId}` : ''}, not from a code edit. The GovOS server re-checks this link on its schedule; the badge on the card shows the latest result.`
      }
    };
  }
  const academic = kind === 'TRUSTED_PUBLIC';
  return {
    ...common,
    type: 'THIRD_PARTY',
    recommendedFor: academic
      ? 'An academic or public-body page a GovOS verifier added. Open it to confirm it fits what you need.'
      : 'Orientation only. GovOS did not write it, no authority published it, and GovOS has not fact-checked it. Where it disagrees with the official notice or paper, the official one governs.',
    officialTag: academic
      ? `ADDED ${date} · ACADEMIC / PUBLIC BODY · NOT AN OFFICIAL SOURCE`
      : `ADDED ${date} · THIRD-PARTY · NOT OFFICIAL · NOT FACT-CHECKED`,
    provenance: {
      id: `prov-${a.id}`,
      documentTitle: a.title,
      officialUrl: a.url,
      publishedDate: date,
      verifiedDate: date,
      verifiedBy: `GovOS verifier — added in the Trust Panel on ${date}; the link is checked, the content is not`,
      taxonomyType: 'RECOMMENDATION',
      verificationLevel: 'UNDER_VERIFICATION',
      excerptText: `A third-party page, not a government publication. A GovOS verifier added it to this exam's library${a.findingId ? ` from research finding #${a.findingId}` : ''} on ${date}. GovOS re-checks that the link opens, but does not endorse the site, is not affiliated with it, and has not fact-checked what it publishes. Anything in it that disagrees with the authority's own notice or papers is wrong, and the authority's document governs.`
    }
  };
};

// ==========================================================================
// Where everything that is not study material goes
// ==========================================================================
// The Resource Library lists learning material only (resourceRoleOf). An exam's notices, papers,
// keys and portals are shown here instead, in the section a candidate would look for them in,
// each with its source in plain words. Every panel reads only the exam it is handed.

/** This exam's verifier additions (exam-scoped on the server). */
const useExamAdditions = (examId: string): ResourceAddition[] => {
  const [adds, setAdds] = useState<ResourceAddition[]>([]);
  useEffect(() => {
    let cancelled = false;
    setAdds([]);
    resourceLiveService.additions(examId).then(a => { if (!cancelled) setAdds(a); });
    return () => { cancelled = true; };
  }, [examId]);
  return adds;
};

/** The latest walk of this exam's authority, projected onto this exam. Null while loading or offline. */
const useDiscoveredSources = (examId: string): DiscoveredSources | null => {
  const [found, setFound] = useState<DiscoveredSources | null>(null);
  useEffect(() => {
    let cancelled = false;
    setFound(null);
    sourceDiscoveryService.forExam(examId).then(d => { if (!cancelled) setFound(d); });
    return () => { cancelled = true; };
  }, [examId]);
  return found;
};

const examResourcesFor = (exam: Exam, additions: ResourceAddition[], placement: ResourcePlacement): ResourceItem[] =>
  [...(exam.resources || []), ...additions.map(additionToResource)].filter(r => resourcePlacementOf(r) === placement);

type SourceTone = 'OFFICIAL' | 'TRUSTED' | 'THIRD_PARTY' | 'LEAD';
const SOURCE_TONE_STYLE: Record<SourceTone, { color: string; bg: string }> = {
  OFFICIAL: { color: '#137638', bg: 'rgba(16,185,129,0.12)' },
  TRUSTED: { color: '#235ddd', bg: 'rgba(43,98,235,0.10)' },
  THIRD_PARTY: { color: '#af5109', bg: 'rgba(245,158,11,0.12)' },
  LEAD: { color: 'var(--text-secondary)', bg: 'var(--surface-3)' }
};
const toneOfClass = (c: string): SourceTone =>
  c === 'PRIMARY_OFFICIAL' ? 'OFFICIAL' : c === 'TRUSTED_SECONDARY' ? 'TRUSTED' : c === 'DISCOVERY_ONLY' ? 'LEAD' : 'THIRD_PARTY';
/** A card from the register: official unless it says it is not. */
const sourceOfResource = (r: ResourceItem): { text: string; tone: SourceTone } =>
  r.type === 'THIRD_PARTY' || r.provenance?.taxonomyType === 'RECOMMENDATION'
    ? { text: 'Third-party source — not verified', tone: 'THIRD_PARTY' }
    : { text: 'Official source', tone: 'OFFICIAL' };

const SourceChip: React.FC<{ text: string; tone: SourceTone }> = ({ text, tone }) => (
  <span style={{ padding: '2px 9px', borderRadius: 'var(--radius-full)', background: SOURCE_TONE_STYLE[tone].bg, color: SOURCE_TONE_STYLE[tone].color, fontSize: '0.7rem', fontWeight: 700, whiteSpace: 'nowrap' }}>
    {text}
  </span>
);

const SourceRow: React.FC<{
  kicker: string; title: string; url: string; sub?: string; source: { text: string; tone: SourceTone };
  note?: string; provenance?: DataProvenance; onOpenProvenanceModal?: (p: DataProvenance) => void;
}> = ({ kicker, title, url, sub, source, note, provenance, onOpenProvenanceModal }) => (
  <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '12px', flexWrap: 'wrap', padding: '12px 14px', borderRadius: 'var(--radius-md)', background: 'var(--surface-2)', border: '1px solid var(--border-color)' }}>
    <div style={{ minWidth: 0, flex: '1 1 260px' }}>
      <div style={{ fontSize: '0.68rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>{kicker}</div>
      <div style={{ fontSize: '0.92rem', fontWeight: 700, color: 'var(--text-primary)', lineHeight: 1.35, overflowWrap: 'anywhere' }}>{title}</div>
      {sub && <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', marginTop: '2px' }}>{sub}</div>}
      {note && <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', marginTop: '4px', lineHeight: 1.45 }}>{note}</div>}
    </div>
    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap', flexShrink: 0 }}>
      <SourceChip text={source.text} tone={source.tone} />
      <a href={url} target="_blank" rel="noreferrer" className="btn btn-secondary" style={{ fontSize: '0.76rem', padding: '5px 12px', display: 'inline-flex', alignItems: 'center', gap: '5px' }}>
        Open <ExternalLink size={12} />
      </a>
      {provenance && onOpenProvenanceModal && <EvidenceButton provenance={provenance} onOpen={onOpenProvenanceModal} />}
    </div>
  </div>
);

const relationNote = (item: DiscoveredSourceItem): string => [
  item.relation === 'THIS_EXAM_OTHER_CYCLE'
    ? `Another cycle of this exam${item.identity.cycle ? ` (${item.identity.cycle})` : ''} — not this cycle's document.`
    : item.obtainable ? '' : 'Listed by the authority, but GovOS could not open it.',
  // A link from the authority's own page is a relationship, never ownership.
  item.relationship === 'LINKED_FROM_OFFICIAL'
    ? `Run by ${item.owner || 'another site'}, not by the authority; the authority's own page links to it.`
    : ''
].filter(Boolean).join(' ');

/** This exam's discovered items for one section, under the listing each was found on: every item once,
 *  in the section its own role names (its listing's, where its own role is unknown). */
const discoveredForSection = (discovered: DiscoveredSources | null, section: ResourceSection) => {
  const seen = new Set<string>();
  return (discovered?.repositories || [])
    .map(repo => ({
      repo,
      items: repo.items.filter(i => i.role !== 'DISCOVERY_SIGNAL' && (i.section || repo.section || 'OFFICIAL_LINKS') === section
        && !seen.has(i.url) && (seen.add(i.url), true))
    }))
    .filter(g => g.items.length > 0);
};

const discoveredRow = (item: DiscoveredSourceItem, kicker?: string) => (
  <SourceRow
    key={item.url}
    kicker={kicker || RESOURCE_ROLE_LABEL[item.role] || 'Link'}
    title={item.title}
    url={item.url}
    sub={item.foundOnTitle ? `Listed on: ${item.foundOnTitle}` : undefined}
    source={{ text: item.label || item.sourceLabel || 'Official source', tone: toneOfClass(item.sourceClass) }}
    note={relationNote(item) || undefined}
  />
);

/** "Not found" and "never looked" must never read alike. */
const SEARCH_STATE_WORDS: Record<string, string> = {
  FOUND_VERIFIED: 'found on the authority’s own site and tied to this exam',
  FOUND_AMBIGUOUS: 'listed on the authority’s own site, but nothing listed could be tied to this exam from its own wording; open the listing to check',
  FOUND_UNREADABLE: 'found on the authority’s own site, but GovOS could not open them',
  NOT_FOUND_AFTER_DISCOVERY: 'every listing and item GovOS found on the authority’s site that could hold them was read, and none is for this exam',
  SEARCH_INCOMPLETE: 'none of what GovOS could read on the authority’s site is for this exam, but some listings or items that could hold them were not read, so GovOS cannot say none exist',
  NOT_SEARCHED: 'GovOS could not read any listing on the authority’s site that could hold them, so it cannot say whether they exist'
};

/** Why places were not read, in plain words: "12 not fetched (file limit), 2 pages built by script". */
const NOT_READ_WORDS: Record<string, string> = {
  skipped_due_to_file_budget: 'not fetched (the walk’s file limit)', skipped_due_to_page_budget: 'not read (the walk’s page limit)',
  skipped_due_to_item_budget: 'not recorded (the walk’s item limit)', skipped_due_to_depth: 'too deep for the walk',
  skipped_due_to_script_rendering: 'built by script', skipped_due_to_fetch_failed: 'could not be opened',
  skipped_due_to_refused_address: 'address refused', skipped_due_to_not_opened: 'not opened',
  skipped_due_to_links_not_followed: 'opened, but what they link to was not followed'
};
const notReadWords = (counts?: Record<string, number>): string =>
  Object.entries(counts || {}).map(([k, n]) => `${n} ${NOT_READ_WORDS[k] || k}`).join(', ');

const DiscoveryStatusLine: React.FC<{ exam: Exam; discovered: DiscoveredSources | null }> = ({ exam, discovered }) => {
  if (!discovered) return null;
  const authority = exam.authorityName.split(' (')[0];
  if (discovered.state !== 'DISCOVERED') {
    return (
      <div style={{ fontSize: '0.76rem', color: 'var(--text-muted)', display: 'flex', alignItems: 'flex-start', gap: '6px', lineHeight: 1.5 }}>
        <Info size={12} style={{ flexShrink: 0, marginTop: '3px' }} />
        GovOS has not walked {authority}&apos;s site for this exam yet. That is a gap here, not a statement about what {authority} publishes.
      </div>
    );
  }
  const c = discovered.coverage;
  return (
    <div style={{ fontSize: '0.76rem', color: 'var(--text-muted)', display: 'flex', alignItems: 'flex-start', gap: '6px', lineHeight: 1.5 }}>
      <Info size={12} style={{ flexShrink: 0, marginTop: '3px' }} />
      <span>
        Read from {authority}&apos;s own site{discovered.discoveredAt ? ` on ${discovered.discoveredAt.slice(0, 10)}` : ''}
        {c ? `: ${c.pagesFetched} page${c.pagesFetched === 1 ? '' : 's'} and ${c.officialResources} official link${c.officialResources === 1 ? '' : 's'}` : ''}.
        {c && c.skipped && Object.keys(c.skipped).length > 0
          ? ` Not everything it found could be read: ${notReadWords(c.skipped)}.`
          : c && (c.fetchFailures > 0 || c.unexplored > 0 || c.pagesWithoutLinks > 0)
            ? ` Not everything could be read (${[c.fetchFailures ? `${c.fetchFailures} could not be opened` : '', c.pagesWithoutLinks ? `${c.pagesWithoutLinks} page${c.pagesWithoutLinks === 1 ? '' : 's'} built by script` : '', c.unexplored ? `${c.unexplored} left for a later walk` : ''].filter(Boolean).join(', ')}).`
            : ''}
      </span>
    </div>
  );
};

/** Section 12: the authority's own documents and services that are not study material. */
export const OfficialDocumentsPanel: React.FC<{ exam: Exam; onOpenProvenanceModal: (p: DataProvenance) => void }> = ({ exam, onOpenProvenanceModal }) => {
  const additions = useExamAdditions(exam.id);
  const discovered = useDiscoveredSources(exam.id);
  const docs = examResourcesFor(exam, additions, 'OFFICIAL_LINKS');
  const linked = new Set(docs.map(d => d.url));
  // Only what belongs here: a corrigendum, a result or a syllabus found on the same listings is shown in
  // its own section, and a document listed on two listings is shown once, under the first.
  const repos = discoveredForSection(discovered, 'OFFICIAL_LINKS').map(g => ({ ...g.repo, items: g.items }));
  const portals = (discovered?.portals || []).filter(p => p.role === 'OFFICIAL_PORTAL' && !linked.has(p.url));
  if (docs.length === 0 && repos.length === 0 && portals.length === 0 && !discovered) return null;
  const authority = exam.authorityName.split(' (')[0];
  return (
    <div className="glass-card" style={{ padding: '20px', display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div>
        <h4 style={{ fontSize: '1.05rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>{authority}&apos;s documents and services for {exam.title}</h4>
        <p style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', margin: '4px 0 0', lineHeight: 1.5 }}>
          Notices and the authority&apos;s own portals and pages. These are official records, not study material, so they are not in the Resource Library; corrigenda, results, syllabus, cut-offs and calendars are shown in their own sections.
        </p>
      </div>
      {docs.map(r => (
        <SourceRow key={r.id} kicker={RESOURCE_ROLE_LABEL[resourceRoleOf(r)]} title={r.title} url={r.url} sub={r.author}
          source={sourceOfResource(r)} provenance={r.provenance} onOpenProvenanceModal={onOpenProvenanceModal} />
      ))}
      {repos.map(repo => (
        <div key={repo.url} style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: '8px', flexWrap: 'wrap' }}>
            <h5 style={{ fontSize: '0.92rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>On {authority}&apos;s listing “{repo.title}”</h5>
            <a href={repo.url} target="_blank" rel="noreferrer" style={{ fontSize: '0.76rem', color: '#235ddd', display: 'inline-flex', alignItems: 'center', gap: '4px' }}>Open the listing <ExternalLink size={11} /></a>
          </div>
          <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)' }}>{repo.note}</div>
          {repo.items.map(item => discoveredRow(item))}
        </div>
      ))}
      {portals.length > 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <h5 style={{ fontSize: '0.92rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>Candidate services on {authority}&apos;s site</h5>
          {portals.map(item => discoveredRow(item, 'Official service'))}
        </div>
      )}
      <DiscoveryStatusLine exam={exam} discovered={discovered} />
    </div>
  );
};

/** Section 09: where this exam's question papers and answer keys are published, beside the engine. */
export const QuestionPaperSourcesPanel: React.FC<{ exam: Exam; onOpenProvenanceModal: (p: DataProvenance) => void }> = ({ exam, onOpenProvenanceModal }) => {
  const additions = useExamAdditions(exam.id);
  const discovered = useDiscoveredSources(exam.id);
  // An official question-paper PDF is already listed by the exam's own engine (OfficialPapersPanel).
  const items = examResourcesFor(exam, additions, 'PRACTICE').filter(r => !(r.subject === 'Previous Year Papers' && r.type === 'OFFICIAL_PDF'));
  const practice = discoveredForSection(discovered, 'PRACTICE');
  // The authority's paper and key listings are shown even when nothing on them is this exam's: there,
  // "none of these is yours" is itself the answer. Practice items found on other listings follow them.
  const repos = [
    ...(discovered?.repositories || []).filter(r => r.role === 'QUESTION_PAPER' || r.role === 'ANSWER_KEY')
      .map(r => ({ ...r, items: practice.find(g => g.repo.url === r.url)?.items || [] })),
    ...practice.filter(g => g.repo.role !== 'QUESTION_PAPER' && g.repo.role !== 'ANSWER_KEY').map(g => ({ ...g.repo, items: g.items }))
  ];
  const states = (['QUESTION_PAPER', 'ANSWER_KEY'] as const)
    .map(role => ({ role, st: discovered?.searchStates?.[role] }))
    .filter(x => x.st);
  if (items.length === 0 && repos.length === 0 && states.length === 0) return null;
  const authority = exam.authorityName.split(' (')[0];
  return (
    <div className="glass-card" style={{ padding: '20px', marginTop: '20px', display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div>
        <h4 style={{ fontSize: '1.05rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>Where question papers and answer keys are published</h4>
        <p style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', margin: '4px 0 0', lineHeight: 1.5 }}>
          Links to the papers themselves. A third-party copy is labelled as one: GovOS has not checked it, and where it disagrees with {authority}&apos;s own paper or key, {authority}&apos;s governs.
        </p>
      </div>
      {items.map(r => (
        <SourceRow key={r.id} kicker={RESOURCE_ROLE_LABEL[resourceRoleOf(r)]} title={r.title} url={r.url} sub={r.author}
          source={sourceOfResource(r)} note={r.type === 'THIRD_PARTY' ? r.description : undefined}
          provenance={r.provenance} onOpenProvenanceModal={onOpenProvenanceModal} />
      ))}
      {repos.map(repo => (
        <div key={repo.url} style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <SourceRow kicker={`${authority}'s listing`} title={repo.title} url={repo.url}
            sub={`${repo.itemCount} item${repo.itemCount === 1 ? '' : 's'} listed${repo.listedWithoutLink.length ? `, ${repo.listedWithoutLink.length} without a link` : ''}`}
            source={{ text: repo.sourceLabel || 'Official source', tone: 'OFFICIAL' }} note={repo.note} />
          {repo.items.map(item => discoveredRow(item))}
        </div>
      ))}
      {states.map(({ role, st }) => (
        <div key={role} style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', display: 'flex', alignItems: 'flex-start', gap: '6px', lineHeight: 1.5 }}>
          <Search size={13} style={{ flexShrink: 0, marginTop: '3px' }} />
          <span><strong style={{ color: 'var(--text-primary)' }}>{role === 'QUESTION_PAPER' ? 'Question papers' : 'Answer keys'} for this exam:</strong> {SEARCH_STATE_WORDS[st!.state] || st!.reason}{st!.notRead && Object.keys(st!.notRead).length > 0 ? ` (not read: ${notReadWords(st!.notRead)})` : ''}.</span>
        </div>
      ))}
      <DiscoveryStatusLine exam={exam} discovered={discovered} />
    </div>
  );
};

/** Section 04: where to register and apply, and practical guidance labelled as such. */
export const ApplicationSourcesPanel: React.FC<{ exam: Exam; onOpenProvenanceModal: (p: DataProvenance) => void }> = ({ exam, onOpenProvenanceModal }) => {
  const additions = useExamAdditions(exam.id);
  const discovered = useDiscoveredSources(exam.id);
  const items = examResourcesFor(exam, additions, 'APPLICATION');
  const linked = new Set(items.map(r => r.url));
  const portals = (discovered?.portals || []).filter(p => (p.role === 'OTR_PORTAL' || p.role === 'APPLICATION_PORTAL') && !linked.has(p.url));
  const guidance = discovered?.practicalGuidance || [];
  const listed = discoveredForSection(discovered, 'APPLICATION').flatMap(g => g.items).filter(i => !linked.has(i.url));
  if (items.length === 0 && portals.length === 0 && guidance.length === 0 && listed.length === 0) return null;
  return (
    <div className="glass-card" style={{ padding: '20px', marginTop: '20px', display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div>
        <h4 style={{ fontSize: '1.05rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>Where to register and apply</h4>
        <p style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', margin: '4px 0 0', lineHeight: 1.5 }}>
          The authority&apos;s own registration and application services. A registration portal serves every recruitment the authority runs; the notice says which one is open.
        </p>
      </div>
      {items.map(r => (
        <SourceRow key={r.id} kicker={RESOURCE_ROLE_LABEL[resourceRoleOf(r)]} title={r.title} url={r.url} sub={r.author}
          source={sourceOfResource(r)} provenance={r.provenance} onOpenProvenanceModal={onOpenProvenanceModal} />
      ))}
      {portals.map(item => discoveredRow(item))}
      {listed.map(item => discoveredRow(item))}
      {guidance.length > 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <h5 style={{ fontSize: '0.92rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>Guidance on applying</h5>
          {guidance.map(item => discoveredRow(item, item.label))}
        </div>
      )}
    </div>
  );
};

/** What each section's panel says above the documents it holds. */
const SECTION_PANEL_COPY: Partial<Record<ResourceSection, { title: string; intro: string }>> = {
  CORRIGENDA: { title: 'Corrigenda and addenda', intro: 'Notices that change or add to a published notice, on the authority’s own copies.' },
  ADMIT_CARD: { title: 'Admit-card notices and services', intro: 'Where the authority publishes admit cards and hall tickets. The card itself is served through each candidate’s own login.' },
  RESULTS: { title: 'Result documents', intro: 'Results, merit lists and selection notices the authority published.' },
  SYLLABUS: { title: 'Syllabus documents', intro: 'The syllabus as the authority published it.' },
  CUTOFFS: { title: 'Cut-off documents', intro: 'Cut-off and qualifying-marks sheets the authority published.' },
  EXAM_DAY: { title: 'Exam-day instructions', intro: 'Instructions the authority published for the day of the examination.' },
  DATES: { title: 'Calendars and schedules', intro: 'Examination calendars and schedules the authority published.' },
  PATTERN: { title: 'Exam pattern documents', intro: 'The scheme of examination as the authority published it.' },
  OVERVIEW: { title: 'About this exam', intro: 'The authority’s own explanation of the examination.' }
};
/** Section number -> the placement whose documents its generic panel shows. */
const SECTION_PANEL_FOR: Record<number, ResourceSection> = Object.fromEntries(
  (Object.keys(SECTION_PANEL_COPY) as ResourceSection[]).map(section => [SECTION_OF_PLACEMENT[section].num, section])
);

/** One section's official documents -- from the register and from GovOS's walk of the authority's site --
 *  shown in the section a candidate would look for them in. Each entry appears in exactly one section. */
export const SectionSourcesPanel: React.FC<{ exam: Exam; section: ResourceSection; onOpenProvenanceModal: (p: DataProvenance) => void }> = ({ exam, section, onOpenProvenanceModal }) => {
  const additions = useExamAdditions(exam.id);
  const discovered = useDiscoveredSources(exam.id);
  const docs = examResourcesFor(exam, additions, section);
  const linked = new Set(docs.map(d => d.url));
  const groups = discoveredForSection(discovered, section)
    .map(g => ({ ...g, items: g.items.filter(i => !linked.has(i.url)) }))
    .filter(g => g.items.length > 0);
  const copy = SECTION_PANEL_COPY[section];
  if (!copy || (docs.length === 0 && groups.length === 0)) return null;
  const authority = exam.authorityName.split(' (')[0];
  return (
    <div className="glass-card" style={{ padding: '20px', marginTop: '20px', display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div>
        <h4 style={{ fontSize: '1.05rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>{copy.title} — {authority}</h4>
        <p style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', margin: '4px 0 0', lineHeight: 1.5 }}>{copy.intro}</p>
      </div>
      {docs.map(r => (
        <SourceRow key={r.id} kicker={RESOURCE_ROLE_LABEL[resourceRoleOf(r)]} title={r.title} url={r.url} sub={r.author}
          source={sourceOfResource(r)} provenance={r.provenance} onOpenProvenanceModal={onOpenProvenanceModal} />
      ))}
      {groups.map(({ repo, items }) => (
        <div key={repo.url} style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: '8px', flexWrap: 'wrap' }}>
            <h5 style={{ fontSize: '0.92rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>On {authority}&apos;s listing “{repo.title}”</h5>
            <a href={repo.url} target="_blank" rel="noreferrer" style={{ fontSize: '0.76rem', color: '#235ddd', display: 'inline-flex', alignItems: 'center', gap: '4px' }}>Open the listing <ExternalLink size={11} /></a>
          </div>
          {items.map(item => discoveredRow(item))}
        </div>
      ))}
    </div>
  );
};

/** The authorities' live boards (SSC's notice board, UPSC's What's New): official notices, not study material. */
export const OfficialNoticeBoards: React.FC<{ exam: Exam }> = ({ exam }) => {
  const [sscFeed, setSscFeed] = useState<SscNoticeFeed | null>(null);
  const [noticeScope, setNoticeScope] = useState<'cgl' | 'all'>('cgl');
  const [upscFeed, setUpscFeed] = useState<SscNoticeFeed | null>(null);
  const isSscExam = exam.id.includes('ssc');
  const isUpscExam = exam.id.includes('upsc');
  useEffect(() => {
    let cancelled = false;
    if (!isUpscExam) { setUpscFeed(null); return; }
    resourceLiveService.upscNotices('cse', 8).then(feed => { if (!cancelled) setUpscFeed(feed); });
    return () => { cancelled = true; };
  }, [isUpscExam, exam.id]);
  // SSC's own notice board, scoped to CGL or all of SSC.
  useEffect(() => {
    if (!isSscExam) { setSscFeed(null); return; }
    let cancelled = false;
    resourceLiveService.sscNotices(noticeScope, 8).then(feed => { if (!cancelled) setSscFeed(feed); });
    return () => { cancelled = true; };
  }, [exam.id, noticeScope, isSscExam]);
  const chipStyle = (active: boolean): React.CSSProperties => ({
    padding: '6px 12px', borderRadius: 'var(--radius-full)', border: `1px solid ${active ? 'var(--primary)' : 'var(--border-color)'}`,
    background: active ? 'rgba(99, 102, 241, 0.16)' : 'transparent', color: active ? '#4f46e5' : 'var(--text-secondary)',
    fontSize: '0.78rem', fontWeight: active ? 700 : 500, fontFamily: 'var(--font-sans)', cursor: 'pointer', whiteSpace: 'nowrap'
  });
  if (!isSscExam && !isUpscExam) return null;
  return (
    <>
      {/* Live: UPSC's What's New, for a UPSC exam. The list carries no dates, so the badge says
          when GovOS first saw each item rather than pretending to a publication date. */}
      {isUpscExam && upscFeed && (
        <div className="glass-card" style={{ padding: '20px', background: 'linear-gradient(135deg, rgba(99,102,241,0.10) 0%, #ffffff 60%)', border: '1px solid rgba(99,102,241,0.35)' }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: '8px', marginBottom: '12px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
              <Bell size={18} color="#4f46e5" />
              <h4 style={{ fontSize: '1.05rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>Latest from UPSC's What's New — Civil Services</h4>
              <span className="badge badge-verified" style={{ fontSize: '0.62rem' }}>LIVE · OFFICIAL</span>
            </div>
            <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
              Read {formatFetched(upscFeed.fetchedAt)}{upscFeed.stale ? ' · last good copy' : ''} · <a href={upscFeed.source} target="_blank" rel="noreferrer" style={{ color: '#4f46e5' }}>upsc.gov.in/whats-new</a>
            </span>
          </div>
          {upscFeed.error && upscFeed.items.length === 0 && (
            <div style={{ fontSize: '0.82rem', color: '#af5109' }}>UPSC's page could not be read just now ({upscFeed.error}). Open it directly.</div>
          )}
          {!upscFeed.error && upscFeed.items.length === 0 && (
            <div style={{ fontSize: '0.84rem', color: 'var(--text-secondary)' }}>
              Nothing about the Civil Services Examination among the {upscFeed.total} latest items on UPSC's What's New page right now. The page is re-read every {upscFeed.intervalHours} h; anything new appears here, dated by when GovOS first saw it.
            </div>
          )}
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {upscFeed.items.map(n => (
              <a key={n.id} href={n.files[0]?.url || upscFeed.source} target="_blank" rel="noreferrer" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '10px', padding: '10px 12px', borderRadius: 'var(--radius-sm)', background: 'var(--surface-2)', border: '1px solid var(--border-color)', textDecoration: 'none' }}>
                <span style={{ fontSize: '0.86rem', color: '#334155' }}>{n.headline}</span>
                <span style={{ fontSize: '0.72rem', color: 'var(--text-muted)', whiteSpace: 'nowrap' }}>first seen {n.createdAt} <ExternalLink size={11} /></span>
              </a>
            ))}
          </div>
        </div>
      )}

      {/* Live: SSC's own notice board */}
      {isSscExam && sscFeed && (sscFeed.items.length > 0 || sscFeed.total > 0 || sscFeed.error) && (
        <div className="glass-card" style={{ padding: '20px', background: 'linear-gradient(135deg, rgba(99,102,241,0.10) 0%, #ffffff 60%)', border: '1px solid rgba(99,102,241,0.35)' }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: '8px', marginBottom: '12px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
              <Bell size={18} color="#4f46e5" />
              <h4 style={{ fontSize: '1.05rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>Latest from SSC's notice board</h4>
              <span className="badge badge-verified" style={{ fontSize: '0.62rem' }}>LIVE · OFFICIAL</span>
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
              <button onClick={() => setNoticeScope('cgl')} style={chipStyle(noticeScope === 'cgl')}>CGL only</button>
              <button onClick={() => setNoticeScope('all')} style={chipStyle(noticeScope === 'all')}>All SSC notices</button>
            </div>
          </div>

          {sscFeed.error && sscFeed.items.length === 0 && (
            <div style={{ fontSize: '0.84rem', color: '#af5109' }}>Could not reach SSC's notice board just now ({sscFeed.error}). It is retried automatically.</div>
          )}
          {!sscFeed.error && sscFeed.items.length === 0 && (
            <div style={{ fontSize: '0.84rem', color: 'var(--text-secondary)' }}>
              None of SSC's latest {sscFeed.total} board entries mention CGL. Switch to "All SSC notices" to see the rest.
            </div>
          )}

          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {sscFeed.items.map(n => (
              <div key={n.id} style={{ display: 'flex', alignItems: 'flex-start', gap: '12px', padding: '10px 12px', borderRadius: 'var(--radius-md)', background: 'var(--surface-2)', border: '1px solid var(--border-color)', flexWrap: 'wrap' }}>
                <span style={{ fontSize: '0.74rem', color: '#4f46e5', fontFamily: 'var(--font-mono)', flexShrink: 0, paddingTop: '2px' }}>{n.createdAt}</span>
                <div style={{ flex: 1, minWidth: '220px', fontSize: '0.88rem', color: 'var(--text-primary)', lineHeight: 1.45 }}>{n.headline}</div>
                <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
                  {n.files.map(f => (
                    <a key={f.url} href={f.url} target="_blank" rel="noreferrer" className="btn btn-secondary" style={{ fontSize: '0.74rem', padding: '4px 10px', display: 'inline-flex', alignItems: 'center', gap: '5px' }}>
                      <FileText size={12} /> PDF{f.sizeKb ? ` · ${f.sizeKb} KB` : ''}
                    </a>
                  ))}
                </div>
              </div>
            ))}
          </div>

          <div style={{ marginTop: '10px', fontSize: '0.74rem', color: 'var(--text-muted)', display: 'flex', alignItems: 'center', gap: '6px', flexWrap: 'wrap' }}>
            <Info size={12} />
            Read from ssc.gov.in's own notice-board API, fetched {formatFetched(sscFeed.fetchedAt)}{sscFeed.stale ? ' (could not refresh; showing the last copy)' : ''} · refreshes every {sscFeed.intervalHours} h · every file opens on ssc.gov.in.
            <a href={sscFeed.source} target="_blank" rel="noreferrer" style={{ color: '#4f46e5', display: 'inline-flex', alignItems: 'center', gap: '3px' }}>Open the full board <ExternalLink size={11} /></a>
          </div>
        </div>
      )}

    </>
  );
};

export const ResourceLibrary: React.FC<ResourceLibraryProps> = ({ exam, onOpenResource, onOpenProvenanceModal, showSectionNumber = true }) => {
  const [additions, setAdditions] = useState<ResourceAddition[]>([]);
  // The static register plus whatever the verifier has added at runtime -- and of that, only what is
  // for learning. A notice, a paper or a portal is shown in its own section, whatever its file type.
  const allResources: ResourceItem[] = [...(exam.resources || []), ...additions.map(additionToResource)];
  const resources: ResourceItem[] = allResources.filter(isLearningResource);
  // Where everything that is not study material is shown instead, counted by section.
  const placedElsewhere = new Map<ResourceSection, number>();
  allResources.forEach(r => {
    const placement = resourcePlacementOf(r);
    if (placement !== 'NONE' && placement !== 'RESOURCES') placedElsewhere.set(placement, (placedElsewhere.get(placement) || 0) + 1);
  });

  const [query, setQuery] = useState<string>('');
  const [typeGroup, setTypeGroup] = useState<ResourceTypeGroup>('ALL');
  const [subjectFilter, setSubjectFilter] = useState<string>('ALL');
  const [savedOnly, setSavedOnly] = useState<boolean>(false);
  const [bookmarkIds, setBookmarkIds] = useState<string[]>(() => storageService.getBookmarkedResourceIds());
  const [linkChecks, setLinkChecks] = useState<Record<string, ResourceLinkCheck>>({});
  const [isVerifying, setIsVerifying] = useState<boolean>(false);
  const [verifySummary, setVerifySummary] = useState<string>('');
  const [isNavigatorOpen, setIsNavigatorOpen] = useState<boolean>(false);
  const [channelFeeds, setChannelFeeds] = useState<Record<string, ChannelUploadFeed>>({});
  const [healthMeta, setHealthMeta] = useState<{ lastRun: string | null; pending: number; intervalHours: number } | null>(null);
  // Learning material the authority's own site links to, from the latest walk of it (labelled by source).
  const discovered = useDiscoveredSources(exam.id);
  const linkedLearning = (discovered?.learning || []).filter(item => !allResources.some(r => r.url === item.url));

  useEffect(() => {
    storageService.loadBookmarksFromSQLite().then(setBookmarkIds);
  }, []);

  // A different exam means a different library: clear filters and stale link results.
  useEffect(() => {
    setQuery('');
    setTypeGroup('ALL');
    setSubjectFilter('ALL');
    setSavedOnly(false);
    setLinkChecks({});
    setVerifySummary('');
  }, [exam.id]);

  // ---- derived structure -------------------------------------------------
  const availableGroups = RESOURCE_TYPE_GROUPS.filter(g => resources.some(r => g.types.includes(r.type)));

  const subjectCounts = resources.reduce<Record<string, number>>((acc, r) => {
    acc[r.subject] = (acc[r.subject] || 0) + 1;
    return acc;
  }, {});
  const availableSubjects: string[] = RESOURCE_SUBJECT_ORDER.filter(sub => subjectCounts[sub]);
  Object.keys(subjectCounts).forEach(sub => {
    if (!availableSubjects.includes(sub)) availableSubjects.push(sub);
  });

  const q = query.trim().toLowerCase();
  const activeTypes = RESOURCE_TYPE_GROUPS.find(g => g.key === typeGroup)?.types;

  const matches = resources.filter(r => {
    if (activeTypes && !activeTypes.includes(r.type)) return false;
    if (subjectFilter !== 'ALL' && r.subject !== subjectFilter) return false;
    if (savedOnly && !bookmarkIds.includes(r.id)) return false;
    if (q) {
      const haystack = `${r.title} ${r.author} ${r.description} ${r.recommendedFor} ${r.officialTag || ''} ${r.subject}`.toLowerCase();
      if (!haystack.includes(q)) return false;
    }
    return true;
  });

  const grouped = availableSubjects
    .map(subject => ({ subject, items: matches.filter(r => r.subject === subject) }))
    .filter(g => g.items.length > 0);

  const essentials = resources.filter(r => r.isEssential);
  const officialCount = resources.filter(r => r.type === 'OFFICIAL_PDF' || r.type === 'OFFICIAL_PORTAL').length;
  const savedCount = resources.filter(r => bookmarkIds.includes(r.id)).length;
  const isFiltered = q !== '' || typeGroup !== 'ALL' || subjectFilter !== 'ALL' || savedOnly;

  const resetFilters = () => {
    setQuery('');
    setTypeGroup('ALL');
    setSubjectFilter('ALL');
    setSavedOnly(false);
  };

  // ---- bookmarks ---------------------------------------------------------
  const toggleBookmark = (r: ResourceItem) => {
    setBookmarkIds(storageService.toggleResourceBookmark({ id: r.id, title: r.title, type: r.type, url: r.url }));
  };

  // ---- live link verification -------------------------------------------
  const externalUrls = Array.from(new Set(
    resources.flatMap(r => [r.url, r.directPdfUrl, r.youtubeUrl].filter(isExternalUrl))
  ));

  const channelIds = Array.from(new Set(resources.map(r => channelIdOf(r.url)).filter((c): c is string => !!c)));

  const applyHealth = (health: { results: ResourceLinkCheck[]; lastRun: string | null; pending: number; intervalHours: number }) => {
    const map: Record<string, ResourceLinkCheck> = {};
    health.results.forEach(res => { map[res.url] = res; });
    setLinkChecks(prev => ({ ...prev, ...map }));
    setHealthMeta({ lastRun: health.lastRun, pending: health.pending, intervalHours: health.intervalHours });
  };

  // Live parts of the library: stored link health (checked on the server's schedule),
  // channel uploads, and entries the verifier added at runtime.
  useEffect(() => {
    let cancelled = false;
    let retry: ReturnType<typeof setTimeout> | undefined;
    const load = async () => {
      const adds = await resourceLiveService.additions(exam.id);
      if (cancelled) return;
      setAdditions(adds);
      const urls = Array.from(new Set([
        ...(exam.resources || []).flatMap(r => [r.url, r.directPdfUrl, r.youtubeUrl].filter(isExternalUrl)),
        ...adds.map(a => a.url)
      ])) as string[];
      const ids = Array.from(new Set([...(exam.resources || []), ...adds].map(r => channelIdOf(r.url)).filter((c): c is string => !!c)));
      const [health, uploads] = await Promise.all([
        resourceLiveService.healthSync(urls),
        resourceLiveService.channelUploads(ids)
      ]);
      if (cancelled) return;
      setChannelFeeds(uploads);
      if (health) {
        applyHealth(health);
        if (health.pending > 0) {
          // new links are checked in the background; ask again once they have had time
          retry = setTimeout(async () => {
            const again = await resourceLiveService.healthSync(urls);
            if (again && !cancelled) applyHealth(again);
          }, 15000);
        }
      }
    };
    load();
    return () => { cancelled = true; if (retry) clearTimeout(retry); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [exam.id]);

  const handleVerifyLinks = async () => {
    if (externalUrls.length === 0 || isVerifying) return;
    setIsVerifying(true);
    setVerifySummary('');
    const results = await resourceLiveService.recheck(externalUrls);
    if (results.length > 0) setHealthMeta(prev => ({ lastRun: new Date().toISOString(), pending: 0, intervalHours: prev?.intervalHours || 12 }));
    if (results.length === 0) {
      setVerifySummary('Could not reach the GovOS server to run the check. Start "python app.py" and try again.');
    } else {
      const map: Record<string, ResourceLinkCheck> = {};
      results.forEach(res => { map[res.url] = res; });
      setLinkChecks(map);
      const healthy = results.filter(res => res.status === 'HEALTHY' || res.status === 'REDIRECT').length;
      const blocked = results.filter(res => res.status === 'BLOCKED').length;
      const failing = results.length - healthy - blocked;
      let summary = `${healthy} of ${results.length} external links responded normally`;
      if (blocked > 0) summary += `, ${blocked} block automated checks`;
      if (failing > 0) summary += `, ${failing} could not be confirmed automatically (open to check)`;
      setVerifySummary(summary + '.');
    }
    setIsVerifying(false);
  };

  const linkBadge = (r: ResourceItem): { text: string; color: string; bg: string } | null => {
    const check = linkChecks[r.url];
    if (check) {
      const ok = check.status === 'HEALTHY' || check.status === 'REDIRECT';
      if (ok) return { text: `Live now · HTTP ${check.httpCode}`, color: '#137638', bg: 'rgba(16,185,129,0.12)' };
      if (check.status === 'BLOCKED') return { text: 'Blocks automated checks · open to confirm', color: '#af5109', bg: 'rgba(245,158,11,0.12)' };
      if (check.status === 'UNREACHABLE') return { text: 'Could not reach automatically · open to confirm', color: '#af5109', bg: 'rgba(245,158,11,0.12)' };
      return { text: `Link broken · HTTP ${check.httpCode}`, color: '#b71f1f', bg: 'rgba(239,68,68,0.12)' };
    }
    if (r.linkVerifiedDate) return { text: `Link verified ${formatVerifiedDate(r.linkVerifiedDate)}`, color: '#137638', bg: 'rgba(16,185,129,0.1)' };
    if (r.provenance?.verificationLevel === 'UNDER_VERIFICATION') return { text: 'Link check pending', color: '#af5109', bg: 'rgba(245,158,11,0.1)' };
    return null;
  };

  // ---- primary action per format ----------------------------------------
  const primaryAction = (r: ResourceItem): { label: string; href?: string; onClick?: () => void } => {
    switch (r.resourceFormat) {
      case 'YOUTUBE_COURSE': return { label: 'Watch Video Course', onClick: () => onOpenResource(r) };
      case 'YOUTUBE_CHANNEL': return { label: 'Open Channel on YouTube', href: r.youtubeUrl || r.url };
      case 'OFFICIAL_PORTAL': return { label: 'Open Official Portal', href: r.url };
      case 'EXTERNAL_PAGE': return { label: 'Open on the third-party site', href: r.url };
      case 'ONLINE_TOOL': return { label: 'Launch Tool', href: r.url };
      case 'INTERACTIVE_HANDBOOK': return { label: 'Read Handbook', onClick: () => onOpenResource(r) };
      default:
        if (isPdfResource(r)) {
          return { label: 'Open Official PDF', href: getDirectPdfUrl(r) };
        }
        return { label: 'Open Official Source', href: r.url };
    }
  };

  const chipStyle = (active: boolean, accent: string = 'var(--primary)'): React.CSSProperties => ({
    padding: '6px 12px',
    borderRadius: 'var(--radius-full)',
    border: `1px solid ${active ? accent : 'var(--border-color)'}`,
    background: active ? 'rgba(99, 102, 241, 0.16)' : 'transparent',
    color: active ? '#4f46e5' : 'var(--text-secondary)',
    fontSize: '0.78rem',
    fontWeight: active ? 700 : 500,
    fontFamily: 'var(--font-sans)',
    cursor: 'pointer',
    whiteSpace: 'nowrap',
    display: 'inline-flex',
    alignItems: 'center',
    gap: '6px',
    transition: 'all 0.15s ease'
  });

  const iconButtonStyle: React.CSSProperties = {
    width: '32px',
    height: '32px',
    borderRadius: 'var(--radius-sm)',
    border: '1px solid var(--border-color)',
    background: 'transparent',
    color: 'var(--text-secondary)',
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    cursor: 'pointer',
    flexShrink: 0
  };

  // ---- card -------------------------------------------------------------
  const renderCard = (r: ResourceItem) => {
    const saved = bookmarkIds.includes(r.id);
    const action = primaryAction(r);
    const badge = linkBadge(r);
    const showExternalIcon = isExternalUrl(r.youtubeUrl || r.url) && !action.href;
    const typeColor = resourceTypeColor(r.type);

    return (
      <div
        key={r.id}
        style={{
          padding: '18px',
          borderRadius: 'var(--radius-md)',
          background: 'var(--surface-2)',
          borderTop: `3px solid ${typeColor}`,
          borderRight: `1px solid ${saved ? 'rgba(99, 102, 241, 0.45)' : 'var(--border-color)'}`,
          borderBottom: `1px solid ${saved ? 'rgba(99, 102, 241, 0.45)' : 'var(--border-color)'}`,
          borderLeft: `1px solid ${saved ? 'rgba(99, 102, 241, 0.45)' : 'var(--border-color)'}`,
          display: 'flex',
          flexDirection: 'column',
          gap: '10px'
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '8px' }}>
          <span style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', fontSize: '0.72rem', fontWeight: 700, color: typeColor, textTransform: 'uppercase', letterSpacing: '0.04em' }}>
            <ResourceTypeIcon type={r.type} /> {resourceTypeLabel(r.type)}
            {r.isEssential && (
              <span style={{ marginLeft: '6px', padding: '1px 7px', borderRadius: 'var(--radius-full)', background: 'rgba(16,185,129,0.15)', color: '#137638', fontSize: '0.66rem' }}>
                ESSENTIAL
              </span>
            )}
          </span>
          <button
            onClick={() => toggleBookmark(r)}
            title={saved ? 'Remove from saved' : 'Save for later'}
            aria-label={saved ? 'Remove from saved' : 'Save for later'}
            style={{ ...iconButtonStyle, borderColor: saved ? 'var(--primary)' : 'var(--border-color)', color: saved ? '#4f46e5' : 'var(--text-muted)', background: saved ? 'rgba(99,102,241,0.14)' : 'transparent' }}
          >
            <Bookmark size={15} fill={saved ? '#4f46e5' : 'none'} />
          </button>
        </div>

        <div>
          <h4 style={{ fontSize: '1rem', fontWeight: 800, color: 'var(--text-primary)', margin: '0 0 3px', lineHeight: 1.3 }}>{r.title}</h4>
          <div style={{ fontSize: '0.78rem', color: '#235ddd', fontWeight: 600 }}>{r.author}</div>
        </div>

        <p style={{ fontSize: '0.84rem', color: 'var(--text-secondary)', margin: 0, lineHeight: 1.45, display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical' as any, overflow: 'hidden' }}>
          {r.description}
        </p>

        <div style={{ fontSize: '0.78rem', color: '#137638', lineHeight: 1.4 }}>
          <strong style={{ color: '#137638' }}>Best for:</strong> {r.recommendedFor}
        </div>

        {r.resourceFormat === 'YOUTUBE_CHANNEL' && (() => {
          const cid = channelIdOf(r.url);
          const feed = cid ? channelFeeds[cid] : undefined;
          if (!feed || feed.items.length === 0) return null;
          return (
            <div style={{ borderTop: '1px solid var(--surface-2)', paddingTop: '8px' }}>
              <div style={{ fontSize: '0.68rem', fontWeight: 700, color: '#b71f1f', textTransform: 'uppercase', letterSpacing: '0.04em', marginBottom: '4px' }}>
                Latest uploads · fetched {formatFetched(feed.fetchedAt)}
              </div>
              {feed.items.slice(0, 3).map(v => (
                <a key={v.videoId} href={v.url} target="_blank" rel="noreferrer" title={v.title} style={{ display: 'flex', gap: '8px', fontSize: '0.78rem', color: '#334155', textDecoration: 'none', lineHeight: 1.35, padding: '3px 0' }}>
                  <span style={{ color: 'var(--text-muted)', fontFamily: 'var(--font-mono)', flexShrink: 0 }}>{v.published.slice(5)}</span>
                  <span style={{ display: '-webkit-box', WebkitLineClamp: 1, WebkitBoxOrient: 'vertical' as any, overflow: 'hidden' }}>{v.title}</span>
                </a>
              ))}
            </div>
          );
        })()}

        {(badge || r.officialTag || r.rating) && (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '6px', alignItems: 'center' }}>
            {badge && (
              <span style={{ padding: '2px 9px', borderRadius: 'var(--radius-full)', background: badge.bg, color: badge.color, fontSize: '0.7rem', fontWeight: 700, display: 'inline-flex', alignItems: 'center', gap: '4px' }}>
                <CheckCircle2 size={11} /> {badge.text}
              </span>
            )}
            {r.officialTag && (
              <span style={{ padding: '2px 9px', borderRadius: 'var(--radius-full)', background: 'var(--surface-2)', color: 'var(--text-secondary)', fontSize: '0.68rem', fontWeight: 600 }}>
                {r.officialTag}
              </span>
            )}
            {r.rating && (
              <span style={{ fontSize: '0.72rem', color: '#af5109', fontWeight: 700, display: 'inline-flex', alignItems: 'center', gap: '3px' }}>
                <Star size={11} fill="#af5109" color="#af5109" /> {r.rating}
              </span>
            )}
          </div>
        )}

        <div style={{ display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: '6px', marginTop: 'auto', paddingTop: '10px', borderTop: '1px solid var(--surface-2)' }}>
          {action.href ? (
            <a href={action.href} target="_blank" rel="noreferrer" className="btn btn-emerald" style={{ fontSize: '0.8rem', padding: '7px 14px', display: 'inline-flex', alignItems: 'center', gap: '6px', flex: 1, justifyContent: 'center' }}>
              {action.label} <ExternalLink size={13} />
            </a>
          ) : (
            <button onClick={action.onClick} className="btn btn-emerald" style={{ fontSize: '0.8rem', padding: '7px 14px', display: 'inline-flex', alignItems: 'center', gap: '6px', flex: 1, justifyContent: 'center' }}>
              {r.resourceFormat === 'YOUTUBE_COURSE' || r.resourceFormat === 'YOUTUBE_CHANNEL' ? <PlayCircle size={14} /> : <BookOpen size={14} />} {action.label}
            </button>
          )}

          {isPdfResource(r) && (
            <a href={getDirectPdfUrl(r)} download={r.downloadFileName || `${r.title.replace(/[^a-zA-Z0-9]/g, '_')}.pdf`} target="_blank" rel="noreferrer" title="Download Official PDF" aria-label="Download Official PDF" style={iconButtonStyle}>
              <Download size={14} />
            </a>
          )}
          {isPdfResource(r) && (
            <button onClick={() => onOpenResource(r)} title="Preview Document in App" aria-label="Preview Document in App" style={iconButtonStyle}>
              <BookOpen size={14} />
            </button>
          )}
          {showExternalIcon && (
            <a href={r.youtubeUrl || r.url} target="_blank" rel="noreferrer" title="Open on the source site" aria-label="Open on the source site" style={iconButtonStyle}>
              <ExternalLink size={14} />
            </a>
          )}
          {action.href && (r.inAppHandbookContent || r.provenance) && (
            <button onClick={() => onOpenResource(r)} title="Notes and details" aria-label="Notes and details" style={iconButtonStyle}>
              <Info size={14} />
            </button>
          )}
          {r.provenance && (
            <EvidenceButton provenance={r.provenance!} onOpen={onOpenProvenanceModal} />
          )}
        </div>
      </div>
    );
  };

  // ---- render ---------------------------------------------------------------
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>

      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', flexWrap: 'wrap', gap: '12px' }}>
        <div>
          <h3 style={{ fontSize: '1.4rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>
            {showSectionNumber ? '08 — Resource Library' : `Resource Library — ${exam.title}`}
          </h3>
          <p style={{ color: 'var(--text-secondary)', fontSize: '0.88rem', margin: '4px 0 0 0' }}>
            {resources.length} resources · {officialCount} from official government sources · {savedCount} saved for later
          </p>
          <p style={{ color: 'var(--text-muted)', fontSize: '0.8rem', margin: '6px 0 0 0', maxWidth: '700px', lineHeight: 1.5 }}>
            Kept current automatically: {channelIds.length > 0 ? 'channel uploads refresh every 6 h, and every link is' : 'every link is'}{' '}
            re-checked every {healthMeta?.intervalHours || 12} h on the GovOS server.
            {healthMeta
              ? ` Links last checked ${formatFetched(healthMeta.lastRun)}${healthMeta.pending > 0 ? ` · ${healthMeta.pending} still being checked` : ''}.`
              : ' Start python app.py to enable the live checks.'}
            {!showSectionNumber && ' GovOS stores no study material: every entry opens the publisher\'s own server.'}
          </p>
        </div>
        <button
          onClick={handleVerifyLinks}
          disabled={isVerifying || externalUrls.length === 0}
          className="btn btn-secondary"
          title="Ask the GovOS server to request every external link and report which ones respond"
          style={{ fontSize: '0.8rem', display: 'inline-flex', alignItems: 'center', gap: '6px', opacity: isVerifying ? 0.7 : 1 }}
        >
          <RefreshCw size={14} className={isVerifying ? 'animate-spin' : ''} />
          {isVerifying ? `Checking ${externalUrls.length} links…` : `Verify all ${externalUrls.length} links now`}
        </button>
      </div>

      {verifySummary && (
        <div style={{ padding: '10px 14px', borderRadius: 'var(--radius-md)', background: 'rgba(99,102,241,0.08)', border: '1px solid rgba(99,102,241,0.3)', fontSize: '0.82rem', color: '#4f46e5', display: 'flex', alignItems: 'center', gap: '8px' }}>
          <Info size={14} /> {verifySummary}
        </div>
      )}

      {/* What is not here, and where it is. Nothing moved out of the exam: only out of this list. */}
      {placedElsewhere.size > 0 && (
        <div style={{ padding: '10px 14px', borderRadius: 'var(--radius-md)', background: 'var(--surface-2)', border: '1px solid var(--border-color)', fontSize: '0.82rem', color: 'var(--text-secondary)', display: 'flex', alignItems: 'flex-start', gap: '8px', lineHeight: 1.5 }}>
          <Info size={14} style={{ flexShrink: 0, marginTop: '2px' }} />
          <span>
            This library lists study material, lessons and practice tools only. {exam.authorityName.split(' (')[0]}&apos;s own documents are in the sections they belong to:{' '}
            {[...placedElsewhere.entries()].map(([section, n]) => `${n} in ${SECTION_OF_PLACEMENT[section].label}`).join('; ')}.
          </span>
        </div>
      )}

      {/* Search & filters */}
      <div className="glass-card" style={{ padding: '16px 18px', display: 'flex', flexDirection: 'column', gap: '12px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px', flexWrap: 'wrap' }}>
          <div style={{ position: 'relative', flex: 1, minWidth: '240px' }}>
            <Search size={16} color="var(--text-muted)" style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)' }} />
            <input
              type="text"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search by title, author, subject or use case…"
              aria-label="Search resources"
              style={{ width: '100%', padding: '10px 36px 10px 38px', borderRadius: 'var(--radius-md)', background: 'var(--bg-input)', border: '1px solid var(--border-color)', color: 'var(--text-primary)', fontSize: '0.9rem', fontFamily: 'var(--font-sans)', outline: 'none' }}
            />
            {query && (
              <button onClick={() => setQuery('')} aria-label="Clear search" style={{ position: 'absolute', right: '8px', top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', display: 'flex' }}>
                <X size={15} />
              </button>
            )}
          </div>
          <button onClick={() => setSavedOnly(v => !v)} style={chipStyle(savedOnly)} aria-pressed={savedOnly}>
            <Bookmark size={13} fill={savedOnly ? '#4f46e5' : 'none'} /> Saved ({savedCount})
          </button>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '6px', flexWrap: 'wrap' }}>
          <span style={{ fontSize: '0.68rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.08em', marginRight: '4px' }}>Type</span>
          <button onClick={() => setTypeGroup('ALL')} style={chipStyle(typeGroup === 'ALL')}>All types</button>
          {availableGroups.map(g => (
            <button key={g.key} onClick={() => setTypeGroup(g.key)} style={chipStyle(typeGroup === g.key)}>
              {g.label} ({resources.filter(r => g.types.includes(r.type)).length})
            </button>
          ))}
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '6px', flexWrap: 'wrap' }}>
          <span style={{ fontSize: '0.68rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.08em', marginRight: '4px' }}>Subject</span>
          <button onClick={() => setSubjectFilter('ALL')} style={chipStyle(subjectFilter === 'ALL')}>All subjects</button>
          {availableSubjects.map(sub => (
            <button key={sub} onClick={() => setSubjectFilter(sub)} style={chipStyle(subjectFilter === sub)}>
              {sub} ({subjectCounts[sub]})
            </button>
          ))}
        </div>
      </div>

      {/* Resource Navigator (existing assistant, collapsed by default) */}
      <div style={{ borderRadius: 'var(--radius-md)', border: '1px solid var(--border-color)', background: 'var(--surface-2)' }}>
        <button
          onClick={() => setIsNavigatorOpen(v => !v)}
          style={{ width: '100%', padding: '12px 16px', background: 'none', border: 'none', color: 'var(--text-secondary)', fontFamily: 'var(--font-sans)', fontSize: '0.85rem', fontWeight: 600, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}
        >
          <span style={{ display: 'inline-flex', alignItems: 'center', gap: '8px' }}>
            <Sparkles size={15} color="#235ddd" /> Not sure what to open? Ask the Resource Navigator
          </span>
          <ChevronDown size={15} style={{ transform: isNavigatorOpen ? 'rotate(180deg)' : 'none', transition: 'transform 0.15s ease' }} />
        </button>
        {isNavigatorOpen && (
          <div style={{ padding: '0 12px 12px' }}>
            <ResourceAIAssistant resources={resources} onOpenResourceModal={onOpenResource} exam={exam} />
          </div>
        )}
      </div>

      {/* Linked from the authority's own site, found by GovOS's last walk of it */}
      {!isFiltered && linkedLearning.length > 0 && (
        <div className="glass-card" style={{ padding: '20px', display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <div>
            <h4 style={{ fontSize: '1.05rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>Linked from {exam.authorityName.split(' (')[0]}&apos;s own site</h4>
            <p style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', margin: '4px 0 0', lineHeight: 1.5 }}>
              Practice and learning links the authority&apos;s site points to. Each says who runs it; one run by someone else is labelled so, even though the authority links to it.
            </p>
          </div>
          {linkedLearning.map(item => discoveredRow(item))}
        </div>
      )}

      {/* Start here shelf */}
      {!isFiltered && essentials.length > 0 && (
        <div className="glass-card" style={{ padding: '20px', background: 'linear-gradient(135deg, rgba(16,185,129,0.09) 0%, #ffffff 60%)', border: '1px solid rgba(16,185,129,0.3)' }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: '8px', marginBottom: '14px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <Compass size={18} color="var(--emerald)" />
              <h4 style={{ fontSize: '1.05rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>Start here — the essentials</h4>
            </div>
            <span style={{ fontSize: '0.78rem', color: 'var(--text-secondary)' }}>
              The {essentials.length} sources every candidate should open first
            </span>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(min(280px, 100%), 1fr))', gap: '12px' }}>
            {essentials.map(renderCard)}
          </div>
        </div>
      )}

      {/* Results */}
      {isFiltered && (
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: '8px', fontSize: '0.82rem', color: 'var(--text-secondary)' }}>
          <span>Showing <strong style={{ color: 'var(--text-primary)' }}>{matches.length}</strong> of {resources.length} resources</span>
          <button onClick={resetFilters} className="btn btn-secondary" style={{ fontSize: '0.76rem', padding: '4px 12px' }}>Clear filters</button>
        </div>
      )}

      {resources.length === 0 ? (
        <div className="glass-card" style={{ padding: '32px 24px', textAlign: 'center' }}>
          <BookOpen size={26} color="var(--text-muted)" style={{ marginBottom: '8px' }} />
          <h4 style={{ fontSize: '1.05rem', fontWeight: 800, color: 'var(--text-primary)', marginBottom: '6px' }}>
            {linkedLearning.length > 0 ? `No other study material checked for ${exam.title} yet` : `No study material listed for ${exam.title} yet`}
          </h4>
          <p style={{ color: 'var(--text-secondary)', fontSize: '0.88rem', maxWidth: '520px', margin: '0 auto', lineHeight: 1.55 }}>
            GovOS lists study material here only when it has been checked for this exam. That is a gap in GovOS, not a
            statement that none exists. The authority&apos;s own notices, papers and portals are in Official Links,
            Practice &amp; PYQs and Application &amp; Documents.
          </p>
        </div>
      ) : matches.length === 0 ? (
        <div className="glass-card" style={{ padding: '40px 24px', textAlign: 'center' }}>
          <AlertTriangle size={26} color="var(--text-muted)" style={{ marginBottom: '8px' }} />
          <h4 style={{ fontSize: '1.05rem', fontWeight: 800, color: 'var(--text-primary)', marginBottom: '6px' }}>
            {savedOnly && savedCount === 0 ? 'Nothing saved yet' : 'No resources match'}
          </h4>
          <p style={{ color: 'var(--text-secondary)', fontSize: '0.88rem', maxWidth: '420px', margin: '0 auto 14px' }}>
            {savedOnly && savedCount === 0
              ? 'Tap the bookmark on any resource to keep it here for quick access.'
              : 'Try a broader search term or clear a filter.'}
          </p>
          <button onClick={resetFilters} className="btn btn-primary" style={{ fontSize: '0.84rem' }}>Show everything</button>
        </div>
      ) : (
        grouped.map(group => (
          <section key={group.subject} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            <div style={{ display: 'flex', alignItems: 'baseline', gap: '10px', borderBottom: '1px solid var(--border-color)', paddingBottom: '8px' }}>
              <h4 style={{ fontSize: '1rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>{group.subject}</h4>
              <span style={{ fontSize: '0.76rem', color: 'var(--text-muted)' }}>{group.items.length} resource{group.items.length === 1 ? '' : 's'}</span>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(min(300px, 100%), 1fr))', gap: '14px' }}>
              {group.items.map(renderCard)}
            </div>
          </section>
        ))
      )}
    </div>
  );
};


// ==========================================================================
// ExamDetailView.tsx
// ==========================================================================
/**
 * The 13 parts every exam has, in the order a candidate meets them.
 *
 * `num` is the section's stable id, not its position: notifications (`actionPayload:
 * {section: N}`), the assistant's navigation actions and every internal jump address
 * sections by number. The ids therefore keep their historical values — Admit Card is still
 * 14 — and only the grouping and the names are new. Mock Tests takes a fresh number (17)
 * for the same reason.
 */
// =====================================================================================
// Shared practice infrastructure — presentation only, never configuration
// =====================================================================================
/**
 * These four are the ONLY things every exam's engine is allowed to share, and each is a pure
 * renderer of whatever exam it is handed: it reads nothing but the `Exam` passed in. No pattern,
 * marking rule, topic list, question, timing or label is defined here — those live in each
 * exam's own engine and in its own record. Nothing in this block may import `TOPIC_CATALOG`,
 * `SSC_CGL_EXAM`, or any other exam-specific data.
 */

/** Refuses to render an engine that has been handed the wrong exam. */
const assertExamMatches = (engine: string, expectedId: string, exam: Exam): boolean => {
  if (exam.id === expectedId) return true;
  // Rejected, never relabelled: showing this exam's content under another exam's name is the
  // exact failure the per-exam architecture exists to prevent.
  console.error(
    `[GovOS] ${engine} was handed "${exam.id}" but only serves "${expectedId}". Refusing to render.`
  );
  return false;
};

const PracticeShell: React.FC<{
  exam: Exam;
  scope: PracticeScope;
  patternSummary: string;
  intro: string;
  children: React.ReactNode;
}> = ({ exam, scope, patternSummary, intro, children }) => (
  <div className="animate-fade-in" style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
    <div>
      <h3 style={{ fontSize: '1.4rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>
        {scope === 'MOCKS' ? '17 — Mock Tests' : '09 — Practice & PYQs'}
      </h3>
      <p style={{ color: 'var(--text-secondary)', fontSize: '0.88rem', margin: '4px 0 0 0', lineHeight: 1.55 }}>
        {intro}
      </p>
      <div style={{ marginTop: '8px', display: 'inline-flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
        <span className="badge badge-verified" style={{ fontSize: '0.62rem' }}>{examDisplayCode(exam)}</span>
        <span style={{ fontSize: '0.78rem', color: 'var(--text-muted)', fontWeight: 600 }}>{patternSummary}</span>
      </div>
    </div>
    {children}
  </div>
);

/** A pattern figure's name in words, for the Derived evidence action. */
const PATTERN_FIELD_WORDS: Record<string, string> = {
  marksPerQuestion: 'marks per question', questions: 'the question count', marks: 'the marks',
  durationMinutes: 'the duration', negativeMarking: 'negative marking', negativeMarkPerWrong: 'the penalty',
};

/** One exam's own pattern, read from its own stages. Nothing is assumed about any other exam. */
/**
 * One node of an exam's published structure, and its children beneath it.
 *
 * Renders only what the authority stated. A missing figure is missing, not a zero; a figure
 * GovOS computed from the authority's figures says so; and a row whose cells the document
 * merged across parts is marked for review with its own text kept, because a confident
 * wrong mark is worse than a gap.
 */
const PatternNodeCard: React.FC<{
  node: ExamPatternNode;
  depth: number;
  onOpenProvenanceModal: (p: DataProvenance) => void;
}> = ({ node, depth, onOpenProvenanceModal }) => {
  const derived = new Set(node.derived || []);
  const review = new Set(node.underReview || []);
  const figures: { label: string; value: string; field: string }[] = [];
  if (node.questions !== undefined) figures.push({ label: 'Questions', value: String(node.questions), field: 'questions' });
  if (node.marks !== undefined) figures.push({ label: 'Marks', value: String(node.marks), field: 'marks' });
  if (node.durationMinutes !== undefined) figures.push({ label: 'Minutes', value: String(node.durationMinutes), field: 'durationMinutes' });
  if (node.marksPerQuestion !== undefined) figures.push({ label: 'Marks / question', value: String(node.marksPerQuestion), field: 'marksPerQuestion' });

  return (
    <div style={{
      padding: depth === 0 ? '22px' : '14px 16px',
      borderRadius: depth === 0 ? 'var(--radius-md)' : 'var(--radius-sm)',
      background: depth === 0 ? 'var(--surface-2)' : 'var(--surface-3)',
      border: '1px solid var(--border-color)',
      display: 'flex', flexDirection: 'column', gap: depth === 0 ? '14px' : '8px'
    }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', flexWrap: 'wrap', gap: '10px' }}>
        <div style={{ minWidth: 0 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap', marginBottom: '4px' }}>
            {node.code && <span className="badge badge-verified" style={{ fontSize: '0.62rem' }}>{node.code}</span>}
            <span style={{ fontSize: '0.68rem', fontWeight: 700, color: 'var(--text-muted)', letterSpacing: '0.04em' }}>
              {(node.levelLabel || node.level || '').toUpperCase()}
            </span>
            {node.status === 'NEEDS_REVIEW' && (
              <span className="badge badge-pending" style={{ fontSize: '0.62rem' }}>NEEDS REVIEW</span>
            )}
          </div>
          <h4 style={{ fontSize: depth === 0 ? '1.15rem' : '0.95rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0, lineHeight: 1.35 }}>
            {node.name}
          </h4>
        </div>
        {/* The figures wrap onto their own line on a phone. `flexShrink: 0` here kept the
            whole row at its full width and pushed the page sideways by 215px at 375. */}
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', minWidth: 0 }}>
          {figures.map(f => (
            <span
              key={f.field}
              className="glass-pill"
              style={{ fontSize: '0.75rem' }}
              title={derived.has(f.field)
                ? `${f.label}: computed by GovOS from the figures this document states, not printed as such`
                : `${f.label}, as stated in ${node.provenance ? node.provenance.documentTitle : 'the official document'}`}
            >
              {f.value} {f.label}{derived.has(f.field) ? ' (computed)' : ''}{review.has(f.field) ? ' *' : ''}
            </span>
          ))}
        </div>
      </div>

      {(node.negativeMarking || node.qualifying || node.languages || node.mode || node.questionType || node.sectionalTiming) && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', fontSize: '0.84rem', color: 'var(--text-secondary)' }}>
          {node.negativeMarking && (
            <div><strong>Negative marking:</strong> {node.negativeMarking}
              {derived.has('negativeMarking') ? ' (stated once for the whole stage)' : ''}</div>
          )}
          {node.qualifying && (
            <div>
              <strong>{node.qualifying.qualifyingOnly ? 'Qualifying only:' : 'Qualifying rule:'}</strong>{' '}
              {node.qualifying.minimumPercent !== undefined && `minimum ${node.qualifying.minimumPercent}%. `}
              {node.qualifying.minimumMarks !== undefined && `minimum ${node.qualifying.minimumMarks} marks. `}
              {(node.qualifying.byCategory || []).map(c => `${c.label}: ${c.minimumMarks}`).join(' · ')}
              {node.qualifying.asPrinted && (
                <span style={{ color: 'var(--text-muted)' }}> {node.qualifying.asPrinted}</span>
              )}
            </div>
          )}
          {node.languages && node.languages.length > 0 && (
            <div><strong>Medium:</strong> {node.languages.join(', ')}</div>
          )}
          {node.mode && <div><strong>Mode:</strong> {node.mode}</div>}
          {node.questionType && <div><strong>Question type:</strong> {node.questionType}</div>}
          {node.sectionalTiming && <div>Each section is timed separately.</div>}
          {(node.durationVariants || []).map((v, i) => (
            <div key={i} style={{ color: 'var(--text-muted)' }}>
              {v.minutes} minutes {v.appliesTo}
            </div>
          ))}
        </div>
      )}

      {node.status === 'NEEDS_REVIEW' && node.note && (
        <div style={{ fontSize: '0.8rem', color: 'var(--amber)', lineHeight: 1.5 }}>
          {node.note}
        </div>
      )}

      {/* What was printed opens the node's own evidence; each figure GovOS computed opens a
          Derived record naming the figures it was computed from. */}
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '6px' }}>
        <EvidenceButton provenance={node.provenance as DataProvenance | undefined} onOpen={onOpenProvenanceModal} />
        {Object.entries(node.derivedEvidence || {}).map(([field, prov]) => (
          <EvidenceButton key={field} provenance={prov} onOpen={onOpenProvenanceModal}
            label={`How ${PATTERN_FIELD_WORDS[field] || field} was computed`} />
        ))}
      </div>

      {node.children && node.children.length > 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', marginTop: '2px' }}>
          {node.children.map(child => (
            <PatternNodeCard key={child.id} node={child} depth={depth + 1} onOpenProvenanceModal={onOpenProvenanceModal} />
          ))}
        </div>
      )}
    </div>
  );
};

/**
 * One node of a published syllabus, and whatever the authority put under it.
 *
 * Depth is the document's, not this component's. A node with no children is a node whose
 * children the authority did not publish, and it renders as one rather than as an empty
 * shell: nothing here invents a topic to make a branch look complete.
 */
const SyllabusNodeCard: React.FC<{
  node: ExamSyllabusNode;
  depth: number;
  onOpenProvenanceModal: (p: DataProvenance) => void;
}> = ({ node, depth, onOpenProvenanceModal }) => {
  const [open, setOpen] = React.useState<boolean>(depth < 2);
  const kids = node.children || [];
  const scope = (node.scope || []).map(s => s.label).join(' · ');
  return (
    <div style={{
      padding: depth === 0 ? '18px' : '10px 12px',
      borderRadius: depth === 0 ? 'var(--radius-md)' : 'var(--radius-sm)',
      background: depth === 0 ? 'var(--surface-2)' : depth === 1 ? 'var(--surface-3)' : 'transparent',
      border: depth <= 1 ? '1px solid var(--border-color)' : 'none',
      borderLeft: depth > 1 ? '2px solid var(--border-color)' : undefined,
      marginLeft: depth > 1 ? '10px' : undefined,
      display: 'flex', flexDirection: 'column', gap: depth === 0 ? '12px' : '6px'
    }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', gap: '10px', flexWrap: 'wrap' }}>
        {kids.length > 0 && (
          <button
            onClick={() => setOpen(v => !v)}
            className="btn btn-secondary"
            style={{ padding: '2px 7px', fontSize: '0.7rem', flexShrink: 0 }}
            aria-label={open ? 'Collapse' : 'Expand'}
          >
            {open ? '−' : '+'}
          </button>
        )}
        <div style={{ minWidth: 0, flex: 1 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
            <span style={{ fontSize: '0.66rem', fontWeight: 700, color: 'var(--text-muted)', letterSpacing: '0.04em' }}>
              {(node.levelLabel || '').toUpperCase()}
            </span>
            {node.status === 'NEEDS_REVIEW' && (
              <span className="badge badge-pending" style={{ fontSize: '0.6rem' }}>NEEDS REVIEW</span>
            )}
            {kids.length > 0 && (
              <span style={{ fontSize: '0.66rem', color: 'var(--text-muted)' }}>{kids.length}</span>
            )}
          </div>
          <div style={{
            fontSize: depth === 0 ? '1.05rem' : depth === 1 ? '0.95rem' : '0.88rem',
            fontWeight: depth <= 1 ? 800 : 600,
            color: 'var(--text-primary)', lineHeight: 1.4
          }}>
            {node.title}
          </div>
          {node.note && (
            <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', lineHeight: 1.5, marginTop: '3px' }}>
              {node.note}
            </div>
          )}
          {scope && depth <= 1 && (
            <div style={{ fontSize: '0.72rem', color: 'var(--text-muted)', marginTop: '3px' }}>
              Applies to: {scope}
            </div>
          )}
        </div>
        {node.provenance && (
          <EvidenceButton provenance={node.provenance as DataProvenance} onOpen={onOpenProvenanceModal} />
        )}
      </div>
      {open && kids.length > 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: depth === 0 ? '8px' : '4px' }}>
          {kids.map(child => (
            <SyllabusNodeCard key={child.id} node={child} depth={depth + 1} onOpenProvenanceModal={onOpenProvenanceModal} />
          ))}
        </div>
      )}
    </div>
  );
};

/**
 * The published syllabus, or an honest statement that there is none.
 *
 * Two different absences, and they are not the same thing. An authority that publishes no
 * syllabus is a fact about that authority, and the section says so and points at what it
 * does publish. A syllabus GovOS has not read yet is a gap here, and the section says that
 * instead. Neither is filled with another exam's syllabus.
 */
const PublishedSyllabusPanel: React.FC<{
  exam: Exam;
  onOpenProvenanceModal: (p: DataProvenance) => void;
}> = ({ exam, onOpenProvenanceModal }) => {
  const tree = exam.syllabusTree || [];
  const count = React.useMemo(() => {
    const walk = (nodes: ExamSyllabusNode[]): number =>
      nodes.reduce((total, node) => total + 1 + walk(node.children || []), 0);
    return walk(tree);
  }, [tree]);

  if (tree.length === 0) {
    return (
      <div style={{ padding: '18px', borderRadius: 'var(--radius-md)', background: 'var(--surface-2)', border: '1px solid var(--border-color)' }}>
        <div style={{ fontSize: '0.95rem', fontWeight: 800, color: 'var(--text-primary)', marginBottom: '6px' }}>
          No official syllabus has been read for this exam
        </div>
        <div style={{ fontSize: '0.86rem', color: 'var(--text-secondary)', lineHeight: 1.6 }}>
          GovOS reads a syllabus from {exam.authorityName.split(' (')[0]}&apos;s own documents or not at all —
          another exam&apos;s syllabus would be the wrong preparation, however close it looks. Some authorities
          publish no syllabus for a recruitment and name only the subjects of each paper; where that is so, the
          Exam Pattern section has those papers and their sections, from the same notice.
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
      <div style={{ fontSize: '0.86rem', color: 'var(--text-secondary)', lineHeight: 1.6 }}>
        The syllabus as {exam.authorityName.split(' (')[0]} published it — {count} entries at the depth its own
        document uses. Each one opens the clause it was read from.
      </div>
      {tree.map(root => (
        <SyllabusNodeCard key={root.id} node={root} depth={0} onOpenProvenanceModal={onOpenProvenanceModal} />
      ))}
    </div>
  );
};

const ExamPatternPanel: React.FC<{ exam: Exam }> = ({ exam }) => (
  <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
    <h4 style={{ fontSize: '1rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>
      What this exam is scored on
    </h4>
    {exam.stages.map(st => (
      <div key={st.id} style={{ padding: '14px 16px', borderRadius: 'var(--radius-md)', background: 'var(--surface-2)', border: '1px solid var(--border-color)' }}>
        <div style={{ fontSize: '0.92rem', fontWeight: 700, color: 'var(--text-primary)' }}>{st.stageName}</div>
        <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', marginTop: '3px' }}>
          {st.totalMarks} marks{st.durationMinutes ? ` · ${st.durationMinutes} minutes` : ''}
          {st.negativeMarking ? ` · negative marking: ${st.negativeMarking}` : ''}
        </div>
        {st.sections && st.sections.length > 0 && (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '6px', marginTop: '8px' }}>
            {st.sections.map((sec, i) => (
              <span key={i} className="glass-pill" style={{ fontSize: '0.74rem' }}>
                {sec.sectionName}{sec.questions ? ` · ${sec.questions} Q` : ''}{sec.marks ? ` · ${sec.marks} marks` : ''}
              </span>
            ))}
          </div>
        )}
      </div>
    ))}
  </div>
);

/**
 * The answer keys an authority has issued for this exam, each bound to an exact paper.
 *
 * A key is shown with the paper it answers, the kind of key it is and when it went up. Where
 * the authority publishes the answers themselves they are shown; where it serves them only
 * to each candidate, the panel says so and says how to reach them. Nothing fills that gap.
 */
const AnswerKeyPanel: React.FC<{
  exam: Exam;
  onOpenProvenanceModal: (p: DataProvenance) => void;
}> = ({ exam, onOpenProvenanceModal }) => {
  const keys = (exam.answerKeys || []).filter(k => k.identity.examId === exam.id);
  if (keys.length === 0) return null;
  // This page's own cycle: the record's, or the year in its title.
  const examCycle = (exam as Exam & { cycle?: string }).cycle || (exam.title.match(/\b(20\d{2})\b/) || [])[1] || '';
  const otherCyclesOnly = examCycle !== '' && keys.every(k => k.identity.cycle && k.identity.cycle !== examCycle);
  const byPaper = new Map<string, ExamAnswerKey[]>();
  keys.forEach(k => {
    const list = byPaper.get(k.identity.describe);
    if (list) list.push(k); else byPaper.set(k.identity.describe, [k]);
  });

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div>
        <h4 style={{ fontSize: '1rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>
          {exam.authorityName.split(' (')[0]}&apos;s own answer keys <span style={{ color: 'var(--text-muted)', fontWeight: 600 }}>({keys.length})</span>
        </h4>
        <p style={{ fontSize: '0.84rem', color: 'var(--text-secondary)', margin: '4px 0 0 0', lineHeight: 1.55 }}>
          Each key below names the exact paper it answers — the cycle, the stage and the sitting the
          authority printed. A later key does not replace an earlier one here: both are kept, because a
          candidate who challenged an answer needs to see what changed.
          {otherCyclesOnly && <> <strong>All of them belong to other cycles; GovOS has read no answer key for {examCycle}.</strong></>}
        </p>
      </div>
      {[...byPaper.entries()].map(([describe, group]) => (
        <div key={describe} style={{ padding: '16px 18px', borderRadius: 'var(--radius-md)', background: 'var(--surface-2)', border: '1px solid var(--border-color)', display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <div style={{ fontSize: '0.95rem', fontWeight: 800, color: 'var(--text-primary)' }}>
            {describe}
            {group[0].identity.cycle && examCycle && group[0].identity.cycle !== examCycle && (
              <span className="badge badge-demo" style={{ fontSize: '0.62rem', marginLeft: '8px' }}>
                Another cycle ({group[0].identity.cycle}) — not a {examCycle} key
              </span>
            )}
          </div>
          {group.map(key => {
            const official = key.sourceStatus === 'OFFICIAL_VERIFIED';
            const supersedes = group.find(other => other.id === key.revises);
            return (
              <div key={key.id} style={{ padding: '12px 14px', borderRadius: 'var(--radius-sm)', background: 'var(--surface-3)', border: '1px solid var(--border-color)', display: 'flex', flexDirection: 'column', gap: '6px' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
                  <span className={official ? 'badge badge-verified' : 'badge badge-pending'} style={{ fontSize: '0.62rem' }}>
                    {key.kind}
                  </span>
                  {official
                    ? <span style={{ fontSize: '0.7rem', color: 'var(--emerald)', fontWeight: 700 }}>OFFICIAL</span>
                    : <span style={{ fontSize: '0.7rem', color: 'var(--amber)', fontWeight: 700 }}>NEEDS REVIEW</span>}
                  {key.publishedAt && (
                    <span style={{ fontSize: '0.74rem', color: 'var(--text-muted)' }}>published {key.publishedAt}</span>
                  )}
                  {supersedes && (
                    <span style={{ fontSize: '0.72rem', color: 'var(--text-muted)' }}>
                      supersedes the {supersedes.kind.toLowerCase()} key
                    </span>
                  )}
                </div>
                {(key.windowOpens || key.windowCloses) && (
                  <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)' }}>
                    Viewable {key.windowOpens || '?'} to {key.windowCloses || '?'}
                  </div>
                )}
                {(key.entries && key.entries.length > 0) ? (
                  <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)' }}>
                    {key.entries.length} answers published with this key.
                  </div>
                ) : (
                  <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', lineHeight: 1.5 }}>
                    {key.note || 'The authority announced this key; its per-question answers are not published publicly.'}
                  </div>
                )}
                <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                  {key.url && (
                    <a href={key.url} target="_blank" rel="noreferrer" className="btn btn-secondary" style={{ fontSize: '0.74rem', padding: '5px 10px', textDecoration: 'none', display: 'inline-flex', alignItems: 'center', gap: '5px' }}>
                      <ExternalLink size={12} /> Open the notice
                    </a>
                  )}
                  {key.provenance && (
                    <EvidenceButton provenance={key.provenance as DataProvenance} onOpen={onOpenProvenanceModal} />
                  )}
                </div>
              </div>
            );
          })}
        </div>
      ))}
    </div>
  );
};

/**
 * The papers this exam's authority publishes, as its own catalogue.
 *
 * Every entry carries the exact identity the authority's own naming gives it, so a paper of
 * another of its examinations — or of another cycle, stage or optional subject — cannot be
 * shown here. A paper GovOS has not transcribed says why, which is a fact about the file
 * rather than about the authority.
 */
const OfficialPaperCatalogue: React.FC<{
  exam: Exam;
  onOpenProvenanceModal: (p: DataProvenance) => void;
}> = ({ exam, onOpenProvenanceModal }) => {
  const papers = (exam.officialPapers || []).filter(p => p.identity.examId === exam.id);
  const [cycle, setCycle] = useState<string>('ALL');
  if (papers.length === 0) return null;
  const cycles = Array.from(new Set(papers.map(p => p.identity.cycle || 'undated'))).sort().reverse();
  const shown = papers.filter(p => cycle === 'ALL' || (p.identity.cycle || 'undated') === cycle);
  const transcribed = papers.filter(p => p.contentsStatus === 'VERIFIED').length;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div>
        <h4 style={{ fontSize: '1rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>
          {exam.authorityName.split(' (')[0]}&apos;s own question papers <span style={{ color: 'var(--text-muted)', fontWeight: 600 }}>({papers.length})</span>
        </h4>
        <p style={{ fontSize: '0.84rem', color: 'var(--text-secondary)', margin: '4px 0 0 0', lineHeight: 1.55 }}>
          Read from the authority&apos;s own listing, and filtered to this exam by each file&apos;s own naming —
          a listing that carries every examination an authority conducts cannot vouch for any one of them.
          {transcribed === 0 && ' None has been transcribed into questions here; each card says why.'}
        </p>
      </div>
      <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
        {['ALL', ...cycles].map(option => (
          <button
            key={option}
            onClick={() => setCycle(option)}
            className={`btn ${cycle === option ? 'btn-primary' : 'btn-secondary'}`}
            style={{ fontSize: '0.76rem', padding: '5px 11px' }}
          >
            {option === 'ALL' ? `All cycles (${papers.length})` : option}
          </button>
        ))}
      </div>
      <div className="grid-2">
        {shown.slice(0, 60).map(paper => (
          <div key={paper.id} style={{ padding: '14px 16px', borderRadius: 'var(--radius-md)', background: 'var(--surface-2)', border: '1px solid var(--border-color)', display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
              <span className="badge badge-verified" style={{ fontSize: '0.6rem' }}>OFFICIAL PAPER</span>
              <span style={{ fontSize: '0.74rem', color: 'var(--text-muted)', fontWeight: 700 }}>
                {paper.identity.describe}
              </span>
            </div>
            {paper.contentsNote && (
              <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', lineHeight: 1.5 }}>
                {paper.contentsNote}
              </div>
            )}
            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
              {paper.url && (
                <a href={paper.url} target="_blank" rel="noreferrer" className="btn btn-primary" style={{ fontSize: '0.75rem', padding: '5px 11px', textDecoration: 'none', display: 'inline-flex', alignItems: 'center', gap: '5px' }}>
                  <ExternalLink size={12} /> Open the paper
                </a>
              )}
              {paper.provenance && (
                <EvidenceButton provenance={paper.provenance as DataProvenance} onOpen={onOpenProvenanceModal} />
              )}
            </div>
          </div>
        ))}
      </div>
      {shown.length > 60 && (
        <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
          Showing 60 of {shown.length}. Narrow by cycle to see the rest.
        </div>
      )}
    </div>
  );
};

/** One exam's own official papers, from its own resources. Never another exam's. */
const OfficialPapersPanel: React.FC<{ exam: Exam; onOpenProvenanceModal: (p: DataProvenance) => void }> = ({ exam, onOpenProvenanceModal }) => {
  const papers = exam.resources.filter(r => r.subject === 'Previous Year Papers' && r.type === 'OFFICIAL_PDF');
  if (papers.length === 0) return null;
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
      <h4 style={{ fontSize: '1rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>
        {exam.authorityName.split(' (')[0]}&apos;s own question papers <span style={{ color: 'var(--text-muted)', fontWeight: 600 }}>({papers.length})</span>
      </h4>
      <div className="grid-2">
        {papers.map(p => (
          <div key={p.id} style={{ padding: '16px 18px', borderRadius: 'var(--radius-md)', background: 'var(--surface-2)', border: '1px solid var(--border-color)', display: 'flex', flexDirection: 'column', gap: '10px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
              <span className="badge badge-verified" style={{ fontSize: '0.62rem' }}>OFFICIAL PAPER</span>
              {p.officialTag && <span style={{ fontSize: '0.7rem', color: 'var(--text-muted)', fontWeight: 700 }}>{p.officialTag}</span>}
            </div>
            <div style={{ fontSize: '0.95rem', fontWeight: 700, color: 'var(--text-primary)', lineHeight: 1.4 }}>{p.title}</div>
            {p.recommendedFor && <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', lineHeight: 1.5 }}>{p.recommendedFor}</div>}
            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
              <a href={p.directPdfUrl || p.url} target="_blank" rel="noreferrer" className="btn btn-primary" style={{ fontSize: '0.8rem', padding: '7px 14px', display: 'inline-flex', alignItems: 'center', gap: '6px', textDecoration: 'none' }}>
                <ExternalLink size={13} /> Open the paper
              </a>
              {p.provenance && (
                <EvidenceButton provenance={p.provenance!} onOpen={onOpenProvenanceModal} />
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

/** A feature this exam does not have the data for yet. Stated, never faked. */
const FeatureUnavailable: React.FC<{ title: string; reason: string; nextStep?: string }> = ({ title, reason, nextStep }) => (
  <div style={{ padding: '16px 18px', borderRadius: 'var(--radius-md)', background: 'var(--amber-soft)', border: '1px solid rgba(180, 83, 9, 0.3)', display: 'flex', gap: '12px', alignItems: 'flex-start' }}>
    <AlertTriangle size={17} color="#af5109" style={{ flexShrink: 0, marginTop: '2px' }} />
    <div style={{ fontSize: '0.86rem', color: '#92400e', lineHeight: 1.55 }}>
      <strong>{title}</strong>
      <div style={{ marginTop: '4px' }}>{reason}</div>
      {nextStep && <div style={{ marginTop: '4px', color: 'var(--text-secondary)' }}>{nextStep}</div>}
    </div>
  </div>
);

/** This exam's own attempt history. Scoped by its own id, in the query, every time. */
const ExamAttemptHistory: React.FC<{ exam: Exam }> = ({ exam }) => {
  const [attempts, setAttempts] = useState<MockAttemptRecord[]>(() => storageService.getMockAttempts(exam.id));
  const [reloadKey, setReloadKey] = useState<number>(0);
  useEffect(() => {
    let cancelled = false;
    storageService.loadMockAttemptsFromSQLite(exam.id).then(found => {
      if (!cancelled) setAttempts(found.filter(a => canonicalExamId(a.exam_id) === canonicalExamId(exam.id)));
    });
    return () => { cancelled = true; };
  }, [exam.id, reloadKey]);
  // An attempt submitted beside this panel used to appear only after the engine remounted.
  useEffect(() => {
    const onSaved = () => setReloadKey(k => k + 1);
    window.addEventListener('govos:attempt-saved', onSaved);
    return () => window.removeEventListener('govos:attempt-saved', onSaved);
  }, []);
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
      <h4 style={{ fontSize: '1rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>
        Past tests <span style={{ color: 'var(--text-muted)', fontWeight: 600 }}>({attempts.length})</span>
      </h4>
      {attempts.length === 0 ? (
        <div style={{ fontSize: '0.84rem', color: 'var(--text-secondary)' }}>
          No attempts recorded for {exam.title}. This list only ever holds this exam&apos;s attempts.
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
          {attempts.slice(0, 10).map(a => (
            <div key={a.id} style={{ display: 'flex', justifyContent: 'space-between', gap: '12px', flexWrap: 'wrap', padding: '8px 12px', borderRadius: 'var(--radius-sm)', background: 'var(--surface-2)', fontSize: '0.82rem' }}>
              <span style={{ color: 'var(--text-primary)', fontWeight: 600 }}>{a.subject}</span>
              <span style={{ color: 'var(--text-secondary)' }}>{a.score} / {a.total_marks}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

// =====================================================================================
// UPSCPracticeEngine — exam-upsc-cse-2026, and nothing else
// =====================================================================================
/**
 * Serves ONE exam id. Its papers, marking, timing and topics come from the UPSC record alone;
 * it imports no SSC question data, no SSC topic catalogue and no SSC configuration.
 *
 * The CSE is two objective Prelims papers (one of which is only qualifying) followed by nine
 * descriptive papers. None of that is scored the way an SSC Tier-1 paper is, which is why this
 * engine exists rather than a widened shared one.
 */
const UPSC_PRACTICE_CONFIG = {
  examId: 'exam-upsc-cse-2026',
  /** The papers, in the order a candidate meets them. Each names the section in UPSC's own record. */
  papers: [
    { group: 'Prelims' as const, key: 'gs1', label: 'General Studies Paper-I', sectionMatch: /General Studies Paper-I/i, paperMatch: /Preliminary.*Paper-I/i, objective: true },
    { group: 'Prelims' as const, key: 'csat', label: 'General Studies Paper-II (CSAT)', sectionMatch: /CSAT/i, paperMatch: /CSAT/i, objective: true },
    { group: 'Mains' as const, key: 'essay', label: 'Paper I — Essay', sectionMatch: /Essay/i, paperMatch: /Essay/i, objective: false },
    { group: 'Mains' as const, key: 'gsI', label: 'Paper II — General Studies-I', sectionMatch: /General Studies-I\b/i, paperMatch: /GENERAL STUDIES PAPER - I\b|General Studies Paper-I \(official/i, objective: false },
    { group: 'Mains' as const, key: 'gsII', label: 'Paper III — General Studies-II', sectionMatch: /General Studies-II\b/i, paperMatch: /General Studies Paper-II \(official/i, objective: false },
    { group: 'Mains' as const, key: 'gsIII', label: 'Paper IV — General Studies-III', sectionMatch: /General Studies-III/i, paperMatch: /General Studies Paper-III/i, objective: false },
    { group: 'Mains' as const, key: 'gsIV', label: 'Paper V — General Studies-IV (Ethics)', sectionMatch: /General Studies-IV/i, paperMatch: /Paper-IV, Ethics/i, objective: false }
  ],
  /** No attemptable item bank exists for the CSE. Saying so is the feature. */
  questionSource: null as null | string
};

/**
 * Answer-writing practice on the CSE's real Essay paper.
 *
 * Every prompt is a question UPSC printed, loaded through `officialQuestionsForExam` with this
 * exam's own id — no other exam's questions can reach here. An essay has no option key and UPSC
 * marks it by examiner assessment, so GovOS records the attempt and never invents a score.
 */
const UpscEssayPractice: React.FC<{ exam: Exam; onOpenProvenanceModal: (p: DataProvenance) => void }> = ({ exam, onOpenProvenanceModal }) => {
  const questions = officialQuestionsForExam(exam.id).filter(q => q.paperName.includes('Essay'));
  const [active, setActive] = useState<OfficialPaperQuestion | null>(null);
  const [answer, setAnswer] = useState<string>('');
  const [startedAt, setStartedAt] = useState<number>(0);
  const [elapsed, setElapsed] = useState<number>(0);
  const [saved, setSaved] = useState<string | null>(null);

  useEffect(() => {
    if (!active) return;
    const t = setInterval(() => setElapsed(Math.floor((Date.now() - startedAt) / 1000)), 1000);
    return () => clearInterval(t);
  }, [active, startedAt]);

  if (questions.length === 0) return null;

  const words = answer.trim() ? answer.trim().split(/\s+/).length : 0;
  const hhmmss = (sec: number) =>
    `${String(Math.floor(sec / 3600)).padStart(2, '0')}:${String(Math.floor((sec % 3600) / 60)).padStart(2, '0')}:${String(sec % 60).padStart(2, '0')}`;

  const submit = () => {
    if (!active) return;
    const seconds = Math.max(1, Math.floor((Date.now() - startedAt) / 1000));
    storageService.saveMockAttempt({
      // The exam is taken from the question's own record, never from the screen or the title.
      id: `upsc-essay-${active.id}-${Date.now()}`,
      exam_id: active.examId,
      subject: `${active.paperName} — Q${active.questionNumber}: ${active.promptEnglish.slice(0, 48)}`,
      score: 0,
      total_marks: active.marks,
      correct_count: 0,
      incorrect_count: 0,
      unattempted_count: 0,
      time_taken_seconds: seconds,
      details: { words, answer, questionId: active.id, notScored: true }
    });
    setSaved(`Saved — ${words} words in ${hhmmss(seconds)}. Not scored: an essay has no official key.`);
    // Tell this exam's history panel to re-read, so the attempt shows without a remount.
    window.dispatchEvent(new CustomEvent('govos:attempt-saved'));
    setActive(null);
    setAnswer('');
  };

  if (active) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '10px' }}>
          <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)', fontWeight: 700 }}>
            {active.paperName} · {active.section} · Q{active.questionNumber} · {active.marks} marks
          </div>
          <div style={{ fontFamily: 'var(--font-mono)', fontSize: '1rem', fontWeight: 800, color: 'var(--primary)' }}>
            {hhmmss(elapsed)}
          </div>
        </div>
        <div style={{ fontSize: '1.08rem', fontWeight: 700, color: 'var(--text-primary)', lineHeight: 1.5 }}>
          {active.promptEnglish}
        </div>
        <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)' }}>
          UPSC asks for about 1000–1200 words. You have written <strong>{words}</strong>.
        </div>
        <textarea
          value={answer}
          onChange={e => setAnswer(e.target.value)}
          placeholder="Write or plan your essay here…"
          style={{ width: '100%', minHeight: '260px', padding: '12px 14px', borderRadius: 'var(--radius-md)', border: '1px solid var(--border-color)', background: '#fff', color: 'var(--text-primary)', fontFamily: 'var(--font-sans)', fontSize: '0.92rem', lineHeight: 1.6, resize: 'vertical' }}
        />
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
          <button className="btn btn-primary" onClick={submit} style={{ fontSize: '0.84rem', padding: '8px 16px' }}>
            Submit &amp; save this attempt
          </button>
          <button className="btn btn-secondary" onClick={() => { setActive(null); setAnswer(''); }} style={{ fontSize: '0.84rem', padding: '8px 16px' }}>
            Cancel
          </button>
          {active.provenance && (
            <EvidenceButton provenance={active.provenance} onOpen={onOpenProvenanceModal} />
          )}
        </div>
      </div>
    );
  }

  const sections = Array.from(new Set(questions.map(q => q.section || '')));
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div>
        <h4 style={{ fontSize: '1rem', fontWeight: 800, color: 'var(--text-primary)', margin: 0 }}>
          Essay answer writing — the real 2026 paper
        </h4>
        <p style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', margin: '4px 0 0 0', lineHeight: 1.5 }}>
          All {questions.length} topics UPSC printed. Two are to be attempted, one from each section, about
          1000–1200 words each, three hours. GovOS records what you write and how long you took; it does not
          mark it, because an essay has no official key and the Commission marks it by examiner assessment.
        </p>
      </div>
      {saved && (
        <div style={{ padding: '10px 14px', borderRadius: 'var(--radius-sm)', background: 'var(--emerald-soft)', color: '#065f46', fontSize: '0.84rem', fontWeight: 600 }}>
          {saved}
        </div>
      )}
      {sections.map(sec => (
        <div key={sec} style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
          <div style={{ fontSize: '0.74rem', fontWeight: 800, letterSpacing: '0.06em', textTransform: 'uppercase', color: 'var(--text-muted)' }}>{sec}</div>
          {questions.filter(q => (q.section || '') === sec).map(q => (
            <div key={q.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '12px', flexWrap: 'wrap', padding: '10px 14px', borderRadius: 'var(--radius-sm)', background: 'var(--surface-2)', border: '1px solid var(--border-color)' }}>
              <span style={{ fontSize: '0.88rem', color: 'var(--text-primary)', fontWeight: 600 }}>
                <span style={{ color: 'var(--text-muted)', fontFamily: 'var(--font-mono)' }}>Q{q.questionNumber}.</span> {q.promptEnglish}
              </span>
              <button className="btn btn-secondary" onClick={() => { setActive(q); setStartedAt(Date.now()); setElapsed(0); setSaved(null); }} style={{ fontSize: '0.78rem', padding: '6px 12px', flexShrink: 0 }}>
                Write this one
              </button>
            </div>
          ))}
        </div>
      ))}
      <div style={{ fontSize: '0.76rem', color: 'var(--text-muted)', lineHeight: 1.5 }}>
        Read from UPSC's own PDF by OCR and marked under verification — open the Evidence on any
        question to check it against the page it came from.
      </div>
    </div>
  );
};

export const UPSCPracticeEngine: React.FC<{
  exam: Exam;
  scope?: PracticeScope;
  onOpenProvenanceModal: (provenance: DataProvenance) => void;
}> = ({ exam, scope = 'ALL', onOpenProvenanceModal }) => {
  if (!assertExamMatches('UPSCPracticeEngine', UPSC_PRACTICE_CONFIG.examId, exam)) return null;
  const [group, setGroup] = useState<'Prelims' | 'Mains'>('Prelims');

  const sectionFor = (re: RegExp) => {
    for (const st of exam.stages) {
      const hit = (st.sections || []).find(s => re.test(s.sectionName));
      if (hit) return { stage: st, section: hit };
    }
    return null;
  };
  const paperFor = (re: RegExp) =>
    exam.resources.find(r => r.subject === 'Previous Year Papers' && r.type === 'OFFICIAL_PDF' && re.test(r.title));

  const shown = UPSC_PRACTICE_CONFIG.papers.filter(p => p.group === group);

  return (
    <PracticeShell
      exam={exam}
      scope={scope}
      patternSummary="Prelims: 2 objective papers · Mains: 9 descriptive papers"
      intro={`${exam.title} practice, built on the Commission's own papers and its own marking. Nothing here is drawn from another exam.`}
    >
      <div style={{ display: 'flex', gap: '6px', background: 'var(--surface-2)', padding: '4px', borderRadius: 'var(--radius-md)', width: 'fit-content' }}>
        {(['Prelims', 'Mains'] as const).map(g => (
          <button key={g} onClick={() => setGroup(g)} className={`btn ${group === g ? 'btn-primary' : 'btn-secondary'}`} style={{ fontSize: '0.82rem', padding: '6px 16px' }}>
            {g === 'Prelims' ? 'Preliminary' : 'Main'}
          </button>
        ))}
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
        {shown.map(p => {
          const found = sectionFor(p.sectionMatch);
          const paper = paperFor(p.paperMatch);
          return (
            <div key={p.key} style={{ padding: '16px 18px', borderRadius: 'var(--radius-md)', background: 'var(--surface-2)', border: '1px solid var(--border-color)', display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <div style={{ fontSize: '0.98rem', fontWeight: 800, color: 'var(--text-primary)' }}>{p.label}</div>
              {found ? (
                <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)' }}>
                  {found.section.questions ? `${found.section.questions} questions · ` : ''}{found.section.marks} marks
                  {found.stage.durationMinutes ? ` · ${found.stage.durationMinutes} minutes` : ''}
                  {found.section.negativeMarking ? ` · negative marking ${found.section.negativeMarking}` : ''}
                </div>
              ) : (
                <div style={{ fontSize: '0.82rem', color: 'var(--text-muted)' }}>Specification not separately itemised in the notice.</div>
              )}
              <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', alignItems: 'center' }}>
                {paper ? (
                  <a href={paper.directPdfUrl || paper.url} target="_blank" rel="noreferrer" className="btn btn-primary" style={{ fontSize: '0.78rem', padding: '6px 12px', display: 'inline-flex', alignItems: 'center', gap: '6px', textDecoration: 'none' }}>
                    <ExternalLink size={12} /> Open the 2026 paper
                  </a>
                ) : (
                  <span style={{ fontSize: '0.78rem', color: 'var(--text-muted)' }}>No 2026 paper on record for this one.</span>
                )}
                <span style={{ fontSize: '0.74rem', color: 'var(--text-muted)' }}>
                  {p.objective ? 'Objective — attemptable once items are transcribed' : 'Descriptive — answer writing, no option key'}
                </span>
              </div>
            </div>
          );
        })}
      </div>

      {group === 'Mains' && <UpscEssayPractice exam={exam} onOpenProvenanceModal={onOpenProvenanceModal} />}

      <FeatureUnavailable
        title={group === 'Prelims' ? 'Prelims tests cannot be scored yet.' : 'Only the Essay paper is attemptable so far.'}
        reason={group === 'Prelims'
          ? "UPSC has published no answer key for CSE 2026 — its Answer Keys page lists none for this cycle — so a Prelims paper cannot be marked without inventing the answers. The booklets are also scans, so each of the 100 items must be transcribed and checked first."
          : "The other Main papers have been read but not yet checked against their pages, so they are not offered for attempt. No question here is generated."}
        nextStep="Open the official papers below and work them on the Commission's own marking, shown on each card."
      />

      <ExamPatternPanel exam={exam} />
      <OfficialPapersPanel exam={exam} onOpenProvenanceModal={onOpenProvenanceModal} />
      {/* The authority's own catalogue and its own keys, each bound to an exact paper.
          Both render nothing where the authority publishes neither, which is why they
          can sit in every engine without an exam-specific branch. */}
      <OfficialPaperCatalogue exam={exam} onOpenProvenanceModal={onOpenProvenanceModal} />
      <AnswerKeyPanel exam={exam} onOpenProvenanceModal={onOpenProvenanceModal} />
      <ExamAttemptHistory exam={exam} />
    </PracticeShell>
  );
};

